window.LICEY_DATA = {"art": [{"id": "a0", "title": "Как смотреть на искусство", "period": "Азбука", "intro": [], "traits": ["Жанры: портрет, пейзаж, натюрморт, историческая, бытовая и религиозная живопись", "Виды: живопись, графика, скульптура, архитектура", "Техники: фреска, темпера, масло, акварель, мозаика", "Перспектива — приём, создающий иллюзию глубины на плоскости", "Светотень (кьяроскуро) — лепка объёма светом и тенью"], "works": [{"t": "Утро в сосновом лесу", "a": "Иван Шишкин и Константин Савицкий", "y": "1889", "d": "Пейзаж: главный герой — природа. Шишкин написал лес, а медведей — его друг Савицкий. Хороший пример, как свет «ведёт» взгляд: солнце пробивается слева сквозь туман.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Shishkin,_Ivan_-_Morning_in_a_Pine_Forest.jpg", "lic": "Public domain", "by": "Ivan Shishkin / Konstantin Savitsky", "src": "media/img/e228ec69ac-1000.webp", "w": 1000, "h": 677, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/Shishkin%2C_Ivan_-_Morning_in_a_Pine_Forest.jpg/1280px-Shishkin%2C_Ivan_-_Morning_in_a_Pine_Forest.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Эту картину вы, скорее всего, видели на обёртке конфет «Мишка косолапый». Её написали в 1889 году два художника. Иван Шишкин нарисовал лес, а медведей добавил его друг Константин Савицкий, который хорошо рисовал животных.", "Сначала на картине стояли обе подписи. Но когда её купил собиратель Павел Третьяков, он стёр подпись Савицкого. Он считал, что главное здесь лес, а значит, картина принадлежит Шишкину.", "Посмотрите на свет. Солнце пробивается слева сквозь утренний туман, и от этого лес кажется живым и тёплым. Шишкин всю жизнь писал русский лес и знал каждую сосну."]}, {"t": "Девятый вал", "a": "Иван Айвазовский", "y": "1850", "d": "Марина — морской пейзаж. Цвет здесь работает как музыка: тёплое солнце против холодной волны, надежда против стихии.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Hovhannes_Aivazovsky_-_The_Ninth_Wave_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Hovhannes Aivazovsky (1817 - 1900) – painter (Russian) Born in Rossiiskaya imper", "src": "media/img/14baff2254-1000.webp", "w": 1000, "h": 672, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Hovhannes_Aivazovsky_-_The_Ninth_Wave_-_Google_Art_Project.jpg/1280px-Hovhannes_Aivazovsky_-_The_Ninth_Wave_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Моряки верили, что во время шторма волны идут сериями, и девятая самая сильная. На картине утро после страшной бури. Корабль утонул, люди держатся за обломок мачты, а на них катится огромная волна.", "Иван Айвазовский написал за жизнь около шести тысяч картин, почти все про море. Удивительно, что с натуры он море не писал. Он смотрел, запоминал и потом рисовал по памяти в мастерской.", "Солнце пробивается сквозь тучи. Тёплый свет против холодной волны. Художник как будто говорит: люди выдержат, надежда есть."]}, {"t": "Богатыри", "a": "Виктор Васнецов", "y": "1898", "d": "Историко-былинная картина. Композиция устойчивая, «каменная»: три фигуры стоят как крепость на заставе.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Viktor_Vasnetsov_-_%D0%91%D0%BE%D0%B3%D0%B0%D1%82%D1%8B%D1%80%D0%B8_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Viktor Vasnetsov", "src": "media/img/daf096c254-1000.webp", "w": 1000, "h": 650, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/Viktor_Vasnetsov_-_%D0%91%D0%BE%D0%B3%D0%B0%D1%82%D1%8B%D1%80%D0%B8_-_Google_Art_Project.jpg/1280px-Viktor_Vasnetsov_-_%D0%91%D0%BE%D0%B3%D0%B0%D1%82%D1%8B%D1%80%D0%B8_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Виктор Васнецов работал над этой картиной почти двадцать лет. Первый набросок он сделал в 1871 году, а закончил в 1898-м.", "В центре Илья Муромец на чёрном коне, слева Добрыня Никитич, справа Алёша Попович. Это герои былин, старинных русских сказаний. Они стоят на границе и смотрят вдаль, не идут ли враги.", "Для лица Добрыни Васнецов взял черты своих родных и свои собственные. А Алёшу писал с сына своего друга, мецената Саввы Мамонтова."]}], "quiz": [{"q": "Как называется жанр живописи, где изображена природа?", "o": ["Натюрморт", "Пейзаж", "Портрет", "Марина"], "a": 1, "e": "Пейзаж — изображение природы. Марина — его разновидность: морской пейзаж."}, {"q": "Что такое натюрморт?", "o": ["Изображение неживых предметов: цветов, посуды, фруктов", "Портрет умершего человека", "Картина на мифологический сюжет", "Роспись по сырой штукатурке"], "a": 0, "e": "Nature morte по-французски — «мёртвая природа»: композиция из предметов."}, {"q": "Роспись по сырой штукатурке называется…", "o": ["Темпера", "Мозаика", "Фреска", "Гравюра"], "a": 2, "e": "Fresco — «свежий»: краски впитываются в сырую штукатурку и живут веками."}, {"q": "Приём, который создаёт иллюзию глубины на плоской картине:", "o": ["Перспектива", "Контраст", "Орнамент", "Колорит"], "a": 0, "e": "Линейная перспектива: параллельные линии сходятся в точке на горизонте."}], "why": ["Экскурсоводы, путеводители и подписи в музеях говорят на своём языке: жанр, фреска, темпера, перспектива. Здесь собраны главные термины, каждый с примером. Разберитесь с ними один раз, и любая картина дальше будет читаться легче."], "groups": [{"h": "Какое бывает искусство", "p": "Сначала главное деление: картина, рисунок, статуя или здание. Это виды изобразительного искусства.", "items": [{"t": "Живопись", "d": "Изображение красками на холсте, доске или стене.", "c": "Леонардо да Винчи. «Мона Лиза»", "more": ["Леонардо да Винчи писал «Мону Лизу» больше десяти лет, начиная примерно с 1503 года, и так и не отдал её заказчику. Скорее всего, на портрете Лиза Герардини, жена флорентийского торговца шёлком.", "Сила живописи в цвете и свете. Посмотрите на лицо: контуры будто растворены в дымке, поэтому выражение кажется то печальным, то улыбающимся. Леонардо добивался этого десятками тончайших полупрозрачных слоёв краски. Этот приём называют сфумато, о нём будет в главе про Возрождение.", "В 1911 году картину украли из Лувра, и два года её искала полиция всего мира. Именно после этой истории «Мона Лиза» стала самой известной картиной на свете."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Mona_Lisa,_by_Leonardo_da_Vinci,_from_C2RMF_retouched.jpg", "lic": "Public domain", "by": "Leonardo da Vinci", "src": "media/img/b6403bc945-1000.webp", "w": 1000, "h": 1490, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg/1280px-Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Графика", "d": "Рисунок и печатная гравюра: карандаш, тушь, уголь.", "c": "Дюрер. «Носорог», гравюра. Он рисовал по описанию, ни разу не видев зверя", "more": ["В 1515 году в Лиссабон привезли из Индии живого носорога, первого в Европе за тысячу лет. Немецкий художник Альбрехт Дюрер его ни разу не видел. Он сделал изображение по чужому письму и наброску, поэтому у зверя панцирь, похожий на рыцарские латы, и лишний рожок на спине.", "Это гравюра. Рисунок вырезают на деревянной доске, покрывают краской и печатают на бумаге, как штампом. С одной доски можно сделать сотни оттисков. Поэтому «Носорог» разошёлся по всей Европе, и почти двести лет даже в учебниках зоологии носорогов рисовали именно так."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Albrecht_D%C3%BCrer,_The_Rhinoceros,_1515,_NGA_47903.jpg", "lic": "CC0", "by": "Albrecht Dürer", "src": "media/img/b96612112b-1000.webp", "w": 1000, "h": 785, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Albrecht_D%C3%BCrer%2C_The_Rhinoceros%2C_1515%2C_NGA_47903.jpg/1280px-Albrecht_D%C3%BCrer%2C_The_Rhinoceros%2C_1515%2C_NGA_47903.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Скульптура", "d": "Объёмная фигура из камня, бронзы, дерева или глины.", "c": "Венера Милосская, Древняя Греция", "more": ["Статую нашёл крестьянин в 1820 году на греческом острове Милос, отсюда название. Её создали около 130 года до нашей эры. Это богиня любви Афродита, римляне называли её Венерой.", "Руки были утрачены ещё до находки. Как она их держала, спорят до сих пор: возможно, в руке было яблоко. В отличие от картины, скульптуру обходят по кругу, и с каждой стороны она выглядит по-новому. Скульптор продумывает все точки зрения сразу. Сейчас Венера стоит в Лувре."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Venus_de_Milo_Louvre_Ma399_n4.jpg", "lic": "Public domain", "by": "Unknown artistUnknown artist", "src": "media/img/c5268119fe-1000.webp", "w": 1000, "h": 1678, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Venus_de_Milo_Louvre_Ma399_n4.jpg/1280px-Venus_de_Milo_Louvre_Ma399_n4.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Архитектура", "d": "Искусство проектировать и строить здания.", "c": "Парфенон в Афинах", "more": ["Парфенон построили в Афинах с 447 по 432 год до нашей эры как храм богини Афины, покровительницы города. Внутри стояла её статуя высотой около 12 метров, покрытая золотом и слоновой костью.", "В нём почти нет прямых линий. Колонны слегка наклонены внутрь и чуть утолщены посередине, а основание немного выгнуто вверх. Дело в том, что издалека идеально прямые линии кажутся провисшими. Греческие архитекторы рассчитали этот обман зрения и исправили его заранее.", "В 1687 году во время войны с венецианцами турки хранили в храме порох. Снаряд попал внутрь, порох взорвался, и Парфенон остался без крыши."], "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Parthenon_in_Athens.jpg", "lic": "CC BY 2.0", "by": "Steve Swayne", "src": "media/img/72aa7cef8d-1000.webp", "w": 1000, "h": 703, "remote": "https://upload.wikimedia.org/wikipedia/commons/d/da/The_Parthenon_in_Athens.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}, {"h": "Что изображают: жанры", "p": "Жанр отвечает на вопрос «что изображено?».", "items": [{"t": "Портрет", "d": "Изображение конкретного человека.", "c": "Вермеер. «Девушка с жемчужной серёжкой»", "more": ["Ян Вермеер жил в голландском городе Делфт в XVII веке и написал всего около 35 картин. Девушка на этой картине, скорее всего, не заказчица. Голландцы называли такие работы «тронье»: этюд головы в необычном костюме, чтобы показать характер и мастерство.", "Посмотрите на свет: блики на губах и в глазах, а жемчужина нарисована всего двумя мазками. Сверху яркий блик, снизу отражение белого воротника. Синюю краску для тюрбана делали из толчёного лазурита, камня, который возили из Афганистана. Она стоила дороже золота."], "img": {"page": "https://commons.wikimedia.org/wiki/File:1665_Girl_with_a_Pearl_Earring.jpg", "lic": "Public domain", "by": "Johannes Vermeer", "src": "media/img/1f01b6178c-1000.webp", "w": 1000, "h": 1184, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/1665_Girl_with_a_Pearl_Earring.jpg/1280px-1665_Girl_with_a_Pearl_Earring.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Пейзаж", "d": "Изображение природы.", "c": "Констебл. «Телега для сена»", "more": ["Джон Констебл всю жизнь писал одни и те же места: деревни на реке Стур в Англии, где он вырос. На картине 1821 года телега переезжает реку вброд. Так делали специально, чтобы деревянные колёса намокли и не рассыхались, а лошади заодно напились.", "В то время пейзаж считали второсортным жанром, гораздо выше ценились исторические и библейские сюжеты. Констебл доказывал, что обычная природа достойна большого холста. В Англии картину не купили, а на выставке в Париже в 1824 году она получила золотую медаль и вдохновила французских художников, будущих импрессионистов."], "img": {"page": "https://commons.wikimedia.org/wiki/File:John_Constable_-_The_Hay_Wain_(1821).jpg", "lic": "Public domain", "by": "John Constable", "src": "media/img/8ec3e1f802-1000.webp", "w": 1000, "h": 690, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/John_Constable_-_The_Hay_Wain_%281821%29.jpg/1280px-John_Constable_-_The_Hay_Wain_%281821%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Марина", "d": "Морской пейзаж.", "c": "Айвазовский. «Девятый вал»", "more": ["Слово «марина» происходит от латинского mare, «море». Морские пейзажи особенно любили в странах, которые жили мореплаванием и торговлей: в Голландии, Англии, позже в России.", "Иван Айвазовский написал около шести тысяч картин, почти все о море. При этом с натуры он море не писал: наблюдал, запоминал и работал по памяти в мастерской. Он говорил, что движение стихий нельзя поймать кистью с натуры, его можно только запомнить. История «Девятого вала» ниже, в разделе «Произведения»."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Hovhannes_Aivazovsky_-_The_Ninth_Wave_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Hovhannes Aivazovsky (1817 - 1900) – painter (Russian) Born in Rossiiskaya imper", "src": "media/img/14baff2254-1000.webp", "w": 1000, "h": 672, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Hovhannes_Aivazovsky_-_The_Ninth_Wave_-_Google_Art_Project.jpg/1280px-Hovhannes_Aivazovsky_-_The_Ninth_Wave_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Натюрморт", "d": "Композиция из предметов: посуда, еда, цветы.", "c": "Хеда. «Завтрак»", "more": ["Виллем Хеда из голландского Харлема писал «завтраки»: недоеденный пирог, опрокинутый бокал, лимон с наполовину снятой кожурой. Почти всё выдержано в серебристо-коричневых тонах.", "Для голландцев XVII века такие картины были с подтекстом. Недопитое вино, погасшая свеча, часы напоминали, что жизнь проходит быстро, а богатство не вечно. Заодно художник показывал мастерство: попробуйте нарисовать отражение окна в изогнутом стекле бокала."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Willem_Claesz._Heda_-_Breakfast_Still-Life_-_WGA11232.jpg", "lic": "Public domain", "by": "Willem Claesz. Heda", "src": "media/img/a187280085-1000.webp", "w": 1000, "h": 744, "remote": "https://upload.wikimedia.org/wikipedia/commons/d/d7/Willem_Claesz._Heda_-_Breakfast_Still-Life_-_WGA11232.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Бытовой жанр", "d": "Сцены повседневной жизни.", "c": "Брейгель. «Крестьянская свадьба»", "more": ["Питер Брейгель написал «Крестьянскую свадьбу» около 1567 года. Невесту найти несложно: она сидит под зелёной тканью, над её головой бумажная корона. А вот где жених, спорят до сих пор, его на картине явно не видно.", "До Брейгеля крестьян почти не делали главными героями. Он вместе с другом ходил на деревенские праздники, переодевшись крестьянином, и наблюдал. Двое мужчин несут миски с кашей на снятой с петель двери, мальчик в огромной шапке облизывает тарелку. Так выглядела настоящая жизнь Фландрии XVI века."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Pieter_Bruegel_the_Elder_-_Peasant_Wedding_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Pieter Bruegel the Elder", "src": "media/img/f9e9cbaf49-1000.webp", "w": 1000, "h": 691, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Pieter_Bruegel_the_Elder_-_Peasant_Wedding_-_Google_Art_Project.jpg/1280px-Pieter_Bruegel_the_Elder_-_Peasant_Wedding_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Историческая картина", "d": "Важные события прошлого: битвы, договоры, коронации.", "c": "Веласкес. «Сдача Бреды»: побеждённый отдаёт ключи от города", "more": ["В 1625 году испанская армия после долгой осады взяла голландский город Бреду. Через десять лет придворный художник Диего Веласкес написал момент сдачи. Голландский командир протягивает ключи от города, а испанский генерал Спинола не даёт ему встать на колени и дружески кладёт руку на плечо.", "Справа строй испанцев с длинными пиками, их так много, что картину иногда называют «Копья». Веласкес показал не торжество победителя, а уважение к побеждённому. Историческая картина считалась тогда самым почётным жанром: она учила зрителя примерами из прошлого."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Velazquez-The_Surrender_of_Breda.jpg", "lic": "Public domain", "by": "Diego Velázquez", "src": "media/img/c2f87ed612-1000.webp", "w": 1000, "h": 825, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/Velazquez-The_Surrender_of_Breda.jpg/1280px-Velazquez-The_Surrender_of_Breda.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Чем рисуют: техники", "p": "Техника отвечает на вопрос «чем и на чём?». От неё зависит, как произведение выглядит и сколько проживёт.", "items": [{"t": "Фреска", "d": "Роспись по сырой штукатурке.", "c": "Джотто. Фреска в часовне в Падуе, около 1305 года", "more": ["Слово «фреска» происходит от итальянского fresco, «свежий». Художник покрывает сырой штукатуркой ровно тот участок стены, который успеет расписать за день. Краска впитывается и, высыхая, становится частью стены. Исправить ошибку можно, только сбив штукатурку и начав заново.", "Около 1305 года Джотто расписал часовню Скровеньи в Падуе: почти сорок сцен из жизни Христа и Марии. На этой фреске ученики оплакивают Христа. Люди склоняются над телом, ангелы в небе рыдают, а две фигуры сидят к нам спиной. Так живо и по-человечески горе до Джотто не изображали. С него начинается путь к Возрождению."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Giotto_-_Scrovegni_-_-36-_-_Lamentation_(The_Mourning_of_Christ)_adj.jpg", "lic": "Public domain", "by": "Giotto", "src": "media/img/1a7c11dd20-1000.webp", "w": 1000, "h": 925, "remote": "https://upload.wikimedia.org/wikipedia/commons/3/3a/Giotto_-_Scrovegni_-_-36-_-_Lamentation_%28The_Mourning_of_Christ%29_adj.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Мозаика", "d": "Изображение из кусочков стекла и камня.", "c": "Императрица Феодора. Равенна, VI век", "more": ["Мозаику набирают из маленьких кубиков цветного стекла, которые называют смальтой. Для золотого фона внутрь стеклянного кубика запаивали тонкую золотую фольгу. Кубики ставили под разным наклоном, чтобы они по-разному ловили свет, и стены мерцали при свечах.", "Эта мозаика в церкви Сан-Витале в итальянском городе Равенна сделана около 547 года. Византийская императрица Феодора несёт в храм золотую чашу. Византийцы любили мозаику ещё и потому, что она не выцветает: этим цветам почти полторы тысячи лет."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Mosaic_of_Theodora_-_Basilica_San_Vitale_(Ravenna).jpg", "lic": "CC BY-SA 4.0", "by": "Petar Milošević", "src": "media/img/b7c048832f-1000.webp", "w": 1000, "h": 592, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Mosaic_of_Theodora_-_Basilica_San_Vitale_%28Ravenna%29.jpg/1280px-Mosaic_of_Theodora_-_Basilica_San_Vitale_%28Ravenna%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Темпера", "d": "Краски на яичном желтке. Ими писали иконы.", "c": "Андрей Рублёв. «Троица»", "more": ["Художник растирал цветной порошок и смешивал его с яичным желтком и водой. Такая краска сохнет за минуты, поэтому писали тонкими слоями, один поверх другого. Основой служила деревянная доска, покрытая белым левкасом, это смесь мела и клея.", "Андрей Рублёв написал «Троицу» в начале XV века для Троице-Сергиева монастыря. На ней три ангела, которые пришли в гости к Аврааму, и одновременно образ Бога в трёх лицах. Фигуры вписаны в круг, без начала и конца: так Рублёв показал согласие и единство. Сейчас икона хранится в Третьяковской галерее."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Angelsatmamre-trinity-rublev-1410.jpg", "lic": "Public domain", "by": "Andrei Rublev", "src": "media/img/567e733b41-1000.webp", "w": 1000, "h": 1245, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Angelsatmamre-trinity-rublev-1410.jpg/1280px-Angelsatmamre-trinity-rublev-1410.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Масло", "d": "Краски на растительном масле.", "c": "Ван Эйк. В зеркале на стене видна вся комната", "more": ["Масляные краски сохнут медленно, по нескольку дней. Их можно смешивать прямо на картине, накладывать прозрачные слои один на другой и писать мельчайшие детали. Нидерландские художники XV века довели эту технику до совершенства, и потом она распространилась по всей Европе.", "Посмотрите на выпуклое зеркало на стене этого портрета 1434 года. В нём отражается вся комната со спины и ещё двое людей в дверях. Один из них, вероятно, сам художник. Над зеркалом надпись на латыни: «Ян ван Эйк был здесь». Такую точность до масляных красок получить было невозможно."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Van_Eyck_-_Arnolfini_Portrait.jpg", "lic": "Public domain", "by": "Jan van Eyck", "src": "media/img/fc05e7255e-1000.webp", "w": 1000, "h": 1368, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Van_Eyck_-_Arnolfini_Portrait.jpg/1280px-Van_Eyck_-_Arnolfini_Portrait.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Акварель", "d": "Прозрачные краски на воде, по бумаге.", "c": "Дюрер. «Заяц»", "more": ["Акварель разводят водой, и сквозь слой краски просвечивает бумага. Поэтому белого цвета в акварели обычно нет: белым остаётся сама бумага. Ошибку почти невозможно исправить, работать нужно быстро и точно.", "Дюрер нарисовал «Зайца» в 1502 году. Шерсть сделана тысячами тонких мазков, а в глазу зайца отражается окно мастерской. Рисунок очень хрупкий: его хранят в Вене и показывают публике редко, чтобы краски не выцвели на свету."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Albrecht_D%C3%BCrer_-_Hare,_1502_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Albrecht Dürer", "src": "media/img/81fb234d1c-1000.webp", "w": 1000, "h": 1105, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/Albrecht_D%C3%BCrer_-_Hare%2C_1502_-_Google_Art_Project.jpg/1280px-Albrecht_D%C3%BCrer_-_Hare%2C_1502_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Как художник обманывает глаз: приёмы", "p": "Картина плоская, но мы видим в ней глубину и объём. Этого добиваются особыми приёмами.", "items": [{"t": "Перспектива", "d": "Иллюзия глубины: дальнее меньше, линии сходятся в одну точку.", "c": "Перуджино. Плиты площади ведут взгляд к храму", "more": ["Линейную перспективу придумали во Флоренции около 1420 года. Архитектор Филиппо Брунеллески показал, что все параллельные линии, которые уходят вдаль, на картине должны сходиться в одной точке на горизонте. С тех пор художники строят пространство почти по законам геометрии.", "Перуджино расписал эту стену Сикстинской капеллы в Риме в 1482 году. Плиты площади нарисованы как расчерченная сетка, и все её линии сходятся к двери храма в центре. Наш взгляд сам идёт туда. Фигуры вдали становятся меньше, и плоская стена превращается в огромную площадь."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Christ_Handing_the_Keys_to_St._Peter_by_Pietro_Perugino.jpg", "lic": "Public domain", "by": "Pietro Perugino", "src": "media/img/d566659d89-1000.webp", "w": 1000, "h": 619, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/1e/Christ_Handing_the_Keys_to_St._Peter_by_Pietro_Perugino.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Светотень", "d": "Объём через контраст света и тени.", "c": "Караваджо. Лица и руки выступают из темноты", "more": ["Итальянцы называли этот приём кьяроскуро, буквально «светло-тёмное». Резкий переход от света к тени делает предметы объёмными, как будто их можно потрогать. Художник Караваджо довёл приём до предела: фон у него почти чёрный, а свет падает узким лучом, как от прожектора.", "На картине 1601 года двое учеников ужинают со случайным странником и вдруг узнают в нём воскресшего Христа. Один вскакивает со стула, другой раскидывает руки. Свет выхватывает лица и руки, и кажется, что персонажи вот-вот выйдут из картины к нам. Корзина с фруктами стоит на самом краю стола и, кажется, сейчас упадёт."], "img": {"page": "https://commons.wikimedia.org/wiki/File:1602-3_Caravaggio,Supper_at_Emmaus_National_Gallery,_London.jpg", "lic": "Public domain", "by": "Caravaggio", "src": "media/img/30559d6da5-1000.webp", "w": 1000, "h": 711, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/1602-3_Caravaggio%2CSupper_at_Emmaus_National_Gallery%2C_London.jpg/1280px-1602-3_Caravaggio%2CSupper_at_Emmaus_National_Gallery%2C_London.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "a1", "title": "Первобытность и Древний Египет", "period": "40 000 лет до н. э. — IV век до н. э.", "intro": [], "traits": ["Наскальная живопись: охра, уголь, звери в движении", "Египетский канон: голова в профиль, плечи анфас", "Размер фигуры = её важность", "Монументальность: пирамиды, сфинкс, храмы", "Искусство служит культу мёртвых и вечности"], "works": [{"t": "Росписи пещеры Ласко", "a": "Неизвестные мастера (Франция)", "y": "около 17 000 лет до н. э.", "d": "Сотни быков, лошадей и оленей, нарисованных углём и глиной. Пещеру нашли подростки в 1940 году.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Lascaux_painting.jpg", "lic": "Public domain", "by": "EU", "src": "media/img/fcc28a34f4-1000.webp", "w": 1000, "h": 656, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/1e/Lascaux_painting.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["В 1940 году четверо подростков во Франции искали подземный ход и случайно провалились в пещеру. На стенах они увидели сотни нарисованных зверей: быков, лошадей, оленей. Рисункам около 17 000 лет.", "Художники работали в полной темноте, при свете каменных ламп с животным жиром. Краски делали из красной и жёлтой глины и угля. Часть краски выдували через полую косточку, как из баллончика.", "После открытия в пещеру пошли тысячи туристов. От их дыхания на стенах начала расти плесень, и рисунки стали портиться. В 1963 году пещеру закрыли. Сейчас посетители смотрят точную копию, построенную рядом."]}, {"t": "Бюст Нефертити", "a": "Скульптор Тутмос", "y": "около 1345 г. до н. э.", "d": "Жена фараона Эхнатона. Эпоха Эхнатона — редкий момент, когда египетский канон стал мягче и живее.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Nofretete_Neues_Museum.jpg", "lic": "CC BY-SA 3.0", "by": "Philip Pikart", "src": "media/img/e03c2fb10a-1000.webp", "w": 1000, "h": 1464, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/Nofretete_Neues_Museum.jpg/1280px-Nofretete_Neues_Museum.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Нефертити была женой фараона Эхнатона. Бюст сделал скульптор Тутмос около 1345 года до нашей эры. Его нашли в 1912 году в развалинах мастерской Тутмоса.", "Скульптура сделана из известняка, покрыта тонким слоем гипса и раскрашена. Посмотрите на глаза: правый вставлен из горного хрусталя, а левый так и остался пустым. Почему, никто точно не знает. Может быть, это была учебная модель для других мастеров.", "Эхнатон хотел поклоняться одному богу, солнцу, и при нём искусство стало мягче и живее, чем обычно в Египте. Сейчас бюст хранится в Берлине."]}, {"t": "Пирамиды Гизы", "a": "Архитекторы фараонов IV династии", "y": "около 2500 г. до н. э.", "d": "Гробницы фараонов Хуфу, Хафра и Менкаура. Пирамида Хеопса — единственное сохранившееся из семи чудес света.", "img": {"page": "https://commons.wikimedia.org/wiki/File:All_Gizah_Pyramids.jpg", "lic": "CC BY-SA 2.0", "by": "Ricardo Liberato", "src": "media/img/dedccf333e-1000.webp", "w": 1000, "h": 665, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/All_Gizah_Pyramids.jpg/1280px-All_Gizah_Pyramids.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Три большие пирамиды построили для трёх фараонов: Хуфу (его ещё называют Хеопсом), его сына Хафра и внука Менкаура. Самая большая, пирамида Хуфу, появилась около 2560 года до нашей эры. Её строили примерно двадцать лет.", "Она сложена из двух миллионов каменных блоков. Каждый весит в среднем как два легковых автомобиля. Высота была 146 метров, почти как пятидесятиэтажный дом. Почти четыре тысячи лет это было самое высокое здание на Земле.", "Раньше думали, что пирамиды строили рабы. Но рядом нашли посёлок строителей с пекарнями и могилами. Оказалось, работали обычные египтяне за еду и плату. Камни тянули на санях по дорогам и насыпям, а песок поливали водой, чтобы сани легче скользили.", "Сначала пирамиды были облицованы гладким белым камнем и блестели на солнце. Потом облицовку разобрали на постройки, и стали видны ступеньки из блоков."]}, {"t": "Маска Тутанхамона", "a": "Египетские мастера", "y": "около 1323 г. до н. э.", "d": "Золото, лазурит, стекло. Маска закрывала лицо мумии юного фараона, гробницу которого нашли нетронутой в 1922 году.", "img": {"page": "https://commons.wikimedia.org/wiki/File:CairoEgMuseumTaaMaskMostlyPhotographed.jpg", "lic": "Public domain", "by": "Roland Unger", "src": "media/img/52271ee97b-1000.webp", "w": 1000, "h": 1250, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/CairoEgMuseumTaaMaskMostlyPhotographed.jpg/1280px-CairoEgMuseumTaaMaskMostlyPhotographed.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Тутанхамон стал фараоном в девять лет и умер примерно в девятнадцать. Великим правителем он не был, зато сегодня его знает весь мир.", "Его гробница была маленькой и спрятанной, поэтому грабители её не нашли. В 1922 году её открыл англичанин Говард Картер. Внутри было больше пяти тысяч вещей: колесницы, мебель, украшения, игры.", "Маска лежала на лице мумии внутри трёх вложенных гробов. Она сделана из золота весом больше десяти килограммов и украшена синим камнем лазуритом и цветным стеклом. Египтяне верили, что золото не тускнеет, как и тело бога."]}], "quiz": [{"q": "Как изображали человека по египетскому канону?", "o": ["Полностью в профиль", "Голова и ноги в профиль, плечи анфас", "Полностью анфас", "Со спины"], "a": 1, "e": "Так каждая часть тела видна в самом «понятном» ракурсе."}, {"q": "Для чего в первую очередь служило искусство Египта?", "o": ["Для украшения жилищ", "Для обеспечения вечной жизни после смерти", "Для торговли", "Для развлечения"], "a": 1, "e": "Гробницы, статуи и росписи помогали душе жить в вечности."}, {"q": "Чем рисовали первобытные художники?", "o": ["Масляными красками", "Охрой и углём", "Акварелью", "Темперой на яйце"], "a": 1, "e": "Природные пигменты: охра (красная и жёлтая глина), уголь, мел."}], "why": ["Египтяне создали одну из первых в мире систем письма, первые огромные каменные постройки и правила рисования, которые не менялись почти три тысячи лет. Их сфинксов и обелиски потом повторяли повсюду, два настоящих египетских сфинкса стоят даже на набережной Невы в Петербурге. А пещерные рисунки показывают, что человек начал рисовать задолго до того, как научился писать."], "groups": [{"h": "Первые художники", "p": "Пещерные рисунки находят по всему миру. Краски делали из глины и угля.", "items": [{"t": "Пещера Ласко", "d": "Сотни зверей, около 17 000 лет назад.", "c": "Франция", "more": ["Около 17 000 лет назад охотники нарисовали в пещере на юге Франции около 600 животных и вырезали на стенах ещё полторы тысячи изображений. Работали при свете каменных светильников с животным жиром.", "Краски делали из охры, это красная и жёлтая глина, и из угля. Иногда краску выдували через полую кость прямо на стену. Зачем рисовали, точно неизвестно. Возможно, это были обряды перед охотой или рассказы о ней. Как пещеру нашли, читайте в разделе «Произведения»."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Lascaux_painting.jpg", "lic": "Public domain", "by": "EU", "src": "media/img/fcc28a34f4-1000.webp", "w": 1000, "h": 656, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/1e/Lascaux_painting.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Пещера Шове", "d": "Около 36 000 лет. Объём за счёт выступов скалы.", "c": "Львы на охоте", "more": ["Пещеру Шове во Франции нашли в 1994 году. Её рисункам около 36 000 лет, вдвое больше, чем в Ласко. Здесь больше всего хищников: львы, медведи, шерстистые носороги.", "Художник выбирал выступы и выпуклости скалы, чтобы спина или голова зверя выглядели объёмными. Некоторые звери нарисованы с несколькими парами ног, словно бегут. Это похоже на первую в истории попытку показать движение."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Lions_painting,_Chauvet_Cave_(museum_replica).jpg", "lic": "Public domain", "by": "HTO", "src": "media/img/1a1d14f43b-1000.webp", "w": 1000, "h": 854, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/Lions_painting%2C_Chauvet_Cave_%28museum_replica%29.jpg/1280px-Lions_painting%2C_Chauvet_Cave_%28museum_replica%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Первые статуэтки", "d": "Фигурки-обереги из камня и кости.", "c": "«Венера Виллендорфская», 11 см, около 25 000 лет", "more": ["Фигурку нашли в 1908 году в Австрии у деревни Виллендорф. Высота всего 11 сантиметров, она помещается в ладони. Её вырезали из известняка около 25 000 лет назад и раскрасили красной охрой.", "Лица у неё нет, голова покрыта как будто косами. Учёные считают, что это символ плодородия и благополучия, оберег, который носили с собой. Название «Венера» дали археологи в шутку, в честь римской богини красоты."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Venus_of_Willendorf_frontview_retouched_2.jpg", "lic": "CC BY 2.5", "by": "User:MatthiasKabel", "src": "media/img/12389dba14-1000.webp", "w": 1000, "h": 1644, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Venus_of_Willendorf_frontview_retouched_2.jpg/1280px-Venus_of_Willendorf_frontview_retouched_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Как узнать египетское искусство", "p": "Если видите эти признаки, перед вами почти наверняка Египет.", "items": [{"t": "Голова сбоку, плечи спереди", "d": "Главное правило египетского канона.", "c": "Небамун охотится на птиц. Роспись гробницы", "more": ["Небамун был писцом, который вёл учёт зерна в храме. Около 1350 года до нашей эры его гробницу расписали сценами счастливой жизни. Здесь он охотится на птиц в зарослях папируса вместе с женой и дочерью, а его кот ловит добычу.", "Египтяне рисовали не то, что видит глаз в одно мгновение, а то, как предмет устроен. Голова лучше узнаётся сбоку, глаз и плечи спереди, ноги сбоку. Фигура выглядит необычно, зато в ней есть всё. Египтяне верили, что изображение будет жить вместо человека в загробном мире, поэтому ни одна часть тела не должна была потеряться."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Tomb_of_Nebamun.jpg", "lic": "Public domain", "by": "anonymous", "src": "media/img/e75471c9b9-1000.webp", "w": 1000, "h": 852, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Tomb_of_Nebamun.jpg/1280px-Tomb_of_Nebamun.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Кто важнее, тот крупнее", "d": "Размер фигуры показывает её важность.", "c": "Палетка Нармера, около 5000 лет", "more": ["Каменная палетка сделана около 3100 года до нашей эры. Это одна из первых записей истории: царь Нармер объединил Верхний и Нижний Египет в одно государство.", "Нармер замахивается булавой на врага, он почти вдвое выше всех. За ним маленький слуга несёт его сандалии. Размер здесь показывает не расстояние, как в перспективе, а важность. Этот приём египтяне сохранили на три тысячи лет."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Narmer_palette_(obverse).jpg", "lic": "Public domain", "by": "anonymous", "src": "media/img/f78c1b74f9-1000.webp", "w": 1000, "h": 1446, "remote": "https://upload.wikimedia.org/wikipedia/commons/5/57/Narmer_palette_%28obverse%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Рисунки рядом с письменами", "d": "Иероглифы подписывают, кто изображён и что происходит.", "c": "«Книга мёртвых». Сердце умершего взвешивают на весах", "more": ["«Книга мёртвых» это свиток папируса с заклинаниями, который клали в гробницу. Он подсказывал умершему, как пройти через загробный мир. Этот свиток сделан для писца Хунефера около 1300 года до нашей эры.", "На картинке загробный суд. Слева бог с головой шакала Анубис ведёт Хунефера к весам. На одной чаше лежит сердце человека, на другой перо богини правды Маат. Египтяне верили, что в сердце хранится память обо всех поступках. Если сердце окажется тяжелее пера, человек жил нечестно, и его съест чудовище Амамат с головой крокодила, которое ждёт у весов.", "Бог мудрости Тот с головой птицы ибиса записывает результат. Сердце Хунефера оказалось лёгким, и справа его ведут к Осирису, владыке загробного мира. Иероглифы над фигурами это подписи и тексты молитв. В Египте изображение и письмо всегда шли рядом, ведь сами иероглифы тоже маленькие рисунки."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Book_of_the_Dead_of_Hunefer_sheet_3.jpg", "lic": "Public domain", "by": "Hunefer", "src": "media/img/62d67ae425-1000.webp", "w": 1000, "h": 457, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Book_of_the_Dead_of_Hunefer_sheet_3.jpg/1280px-Book_of_the_Dead_of_Hunefer_sheet_3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Огромные каменные постройки", "d": "Пирамиды, храмы и сфинксы, рассчитанные на вечность.", "c": "Большой сфинкс в Гизе", "more": ["Большой сфинкс вырезан прямо в скале около 2500 года до нашей эры. Его длина 73 метра, высота 20. У него тело льва, символ силы, и голова фараона, скорее всего Хафры, чья пирамида стоит рядом.", "Тысячи лет сфинкса заносило песком по самую шею, и в древности его не раз откапывали. Нос отбит, когда и кем, точно неизвестно. Сфинкс сторожил дорогу к пирамидам. Его размеры должны были показать мощь фараона и вечность его власти."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Great_Sphinx_(%D8%A3%D8%A8%D9%88_%D8%A7%D9%84%D9%87%D9%88%D9%84).jpg", "lic": "CC BY-SA 4.0", "by": "Petar Milošević", "src": "media/img/4acef234c4-1000.webp", "w": 1000, "h": 646, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/Great_Sphinx_%28%D8%A3%D8%A8%D9%88_%D8%A7%D9%84%D9%87%D9%88%D9%84%29.jpg/1280px-Great_Sphinx_%28%D8%A3%D8%A8%D9%88_%D8%A7%D9%84%D9%87%D9%88%D9%84%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "a2", "title": "Античность: Греция и Рим", "period": "VIII век до н. э. — V век н. э.", "intro": ["Греки сделали главным героем искусства человека. Их идеал — гармония тела и духа, «калокагатия». Скульпторы искали идеальные пропорции и научились показывать тело в движении.", "Важное открытие — контрапост: фигура опирается на одну ногу, и всё тело приходит в живое равновесие. Сравните со скованными египетскими статуями — это революция.", "Римляне многое взяли у греков, но добавили своё: правдивый портрет (со всеми морщинами), арки, купола, бетон, грандиозные постройки — Колизей и Пантеон."], "traits": ["Человек — мера всех вещей", "Идеальные пропорции и гармония", "Контрапост — живая поза с опорой на одну ногу", "Ордера в архитектуре: дорический, ионический, коринфский", "Рим: реалистичный портрет, арки, купола"], "works": [{"t": "Дискобол", "a": "Мирон (римская копия)", "y": "около 450 г. до н. э.", "d": "Атлет за миг до броска. Мирон «остановил» движение — для того времени смелый эксперимент.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Discobolus_in_National_Roman_Museum_Palazzo_Massimo_alle_Terme.JPG", "lic": "CC BY-SA 4.0", "by": "Livioandronico2013", "src": "media/img/7b0a35bc6a-1000.webp", "w": 1000, "h": 1672, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/Discobolus_in_National_Roman_Museum_Palazzo_Massimo_alle_Terme.JPG/1280px-Discobolus_in_National_Roman_Museum_Palazzo_Massimo_alle_Terme.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Венера Милосская", "a": "Предположительно Александрос Антиохийский", "y": "около 130 г. до н. э.", "d": "Эпоха эллинизма. Руки утрачены, но статуя стала символом женской красоты. Хранится в Лувре.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Venus_de_Milo_Louvre_Ma399_n4.jpg", "lic": "Public domain", "by": "Unknown artistUnknown artist", "src": "media/img/c5268119fe-1000.webp", "w": 1000, "h": 1678, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Venus_de_Milo_Louvre_Ma399_n4.jpg/1280px-Venus_de_Milo_Louvre_Ma399_n4.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Ника Самофракийская", "a": "Неизвестный скульптор", "y": "около 190 г. до н. э.", "d": "Богиня победы на носу корабля. Мрамор передаёт ветер и мокрую ткань — вершина эллинистической динамики.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Nike_of_Samothrake_Louvre_Ma2369_n4.jpg", "lic": "Public domain", "by": "", "src": "media/img/53813a5b17-1000.webp", "w": 1000, "h": 1515, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/Nike_of_Samothrake_Louvre_Ma2369_n4.jpg/1280px-Nike_of_Samothrake_Louvre_Ma2369_n4.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Парфенон", "a": "Иктин и Калликрат, скульптор Фидий", "y": "447–438 гг. до н. э.", "d": "Храм Афины на Акрополе — эталон дорического ордера. Колонны чуть наклонены и утолщены, чтобы храм казался идеально ровным.", "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Parthenon_in_Athens.jpg", "lic": "CC BY 2.0", "by": "Steve Swayne", "src": "media/img/72aa7cef8d-1000.webp", "w": 1000, "h": 703, "remote": "https://upload.wikimedia.org/wikipedia/commons/d/da/The_Parthenon_in_Athens.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Колизей", "a": "Римские строители", "y": "72–80 гг. н. э.", "d": "Амфитеатр на 50 000 зрителей. Римская формула: арки, бетон и три греческих ордера на фасаде.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Colosseo_2020.jpg", "lic": "CC BY-SA 4.0", "by": "FeaturedPics", "src": "media/img/9059ffbfcd-1000.webp", "w": 1000, "h": 701, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Colosseo_2020.jpg/1280px-Colosseo_2020.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}], "quiz": [{"q": "Что такое контрапост?", "o": ["Тип колонны", "Поза с опорой на одну ногу, создающая живое равновесие", "Техника литья бронзы", "Роспись вазы"], "a": 1, "e": "Контрапост оживил скульптуру и вернулся в эпоху Возрождения (вспомните «Давида» Микеланджело)."}, {"q": "Какой храм стоит на афинском Акрополе?", "o": ["Пантеон", "Колизей", "Парфенон", "Храм Артемиды"], "a": 2, "e": "Парфенон посвящён Афине-Деве. Пантеон — в Риме."}, {"q": "Что римляне добавили к греческому искусству?", "o": ["Иероглифы", "Правдивый портрет и арочные конструкции", "Иконопись", "Золотой фон"], "a": 1, "e": "Римский портрет честен: морщины, лысины, характер. А арки и бетон дали огромные пространства."}]}, {"id": "a3", "title": "Средневековье: икона, романика, готика", "period": "V — XIV век", "intro": ["После падения Рима искусство Европы стало прежде всего христианским. Его задача — не копировать мир, а показать мир духовный. Поэтому фигуры плоские, золотой фон означает небесный свет, а пропорции подчиняются смыслу.", "Византия подарила миру мозаики и иконы. На Руси икону довёл до совершенства Андрей Рублёв. Обратная перспектива в иконе как бы раскрывает пространство навстречу зрителю.", "На Западе сначала строили тяжёлые романские соборы-крепости, а с XII века — готические: стрельчатые арки, высокие своды, витражи. Готический собор стремится ввысь, к Богу. В конце эпохи Джотто начинает возвращать живописи объём и чувства — это уже порог Возрождения."], "traits": ["Золотой фон — символ божественного света", "Плоские фигуры, обратная перспектива", "Мозаика, икона, витраж, книжная миниатюра", "Готика: стрельчатые арки, витражи, устремлённость вверх", "Анонимность: мастер служит Богу, а не славе"], "works": [{"t": "Троица", "a": "Андрей Рублёв", "y": "1411 или 1425–1427", "d": "Три ангела у стола — образ Святой Троицы. Фигуры вписаны в круг — символ вечности и согласия. Главная русская икона, хранится в Третьяковской галерее.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Angelsatmamre-trinity-rublev-1410.jpg", "lic": "Public domain", "by": "Andrei Rublev", "src": "media/img/567e733b41-1000.webp", "w": 1000, "h": 1245, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Angelsatmamre-trinity-rublev-1410.jpg/1280px-Angelsatmamre-trinity-rublev-1410.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Собор Парижской Богоматери", "a": "Строители-готы", "y": "1163–1345", "d": "Образец ранней готики: розы-витражи, контрфорсы, химеры. Собор вдохновил Гюго на роман.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Notre-Dame_de_Paris_2013-07-24.jpg", "lic": "CC BY-SA 3.0", "by": "P e z i", "src": "media/img/a720a76e0c-1000.webp", "w": 1000, "h": 1350, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Notre-Dame_de_Paris_2013-07-24.jpg/1280px-Notre-Dame_de_Paris_2013-07-24.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Оплакивание Христа", "a": "Джотто ди Бондоне", "y": "около 1305", "d": "Фреска в капелле Скровеньи. Лица полны горя, фигуры объёмны — Джотто первым вернул живописи человеческие чувства.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Giotto_-_Scrovegni_-_-36-_-_Lamentation_(The_Mourning_of_Christ)_adj.jpg", "lic": "Public domain", "by": "Giotto", "src": "media/img/1a7c11dd20-1000.webp", "w": 1000, "h": 925, "remote": "https://upload.wikimedia.org/wikipedia/commons/3/3a/Giotto_-_Scrovegni_-_-36-_-_Lamentation_%28The_Mourning_of_Christ%29_adj.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Император Юстиниан со свитой", "a": "Византийские мастера", "y": "около 547", "d": "Мозаика в Равенне. Фигуры парят без тени, смотрят прямо на нас — так выглядит власть, освящённая небом.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Meister_von_San_Vitale_in_Ravenna.jpg", "lic": "Public domain", "by": "Meister von San Vitale in Ravenna", "src": "media/img/a845c3d3d2-1000.webp", "w": 1000, "h": 1353, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Meister_von_San_Vitale_in_Ravenna.jpg/1280px-Meister_von_San_Vitale_in_Ravenna.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}], "quiz": [{"q": "Что означает золотой фон в иконе?", "o": ["Богатство заказчика", "Божественный свет, небесный мир", "Солнечный день", "Пустыню"], "a": 1, "e": "Золото — не «место», а свет иного мира."}, {"q": "Какие черты отличают готику?", "o": ["Купола и плоские крыши", "Стрельчатые арки, витражи, высота", "Пирамиды и обелиски", "Колонны дорического ордера"], "a": 1, "e": "Готический собор весь стремится вверх, а стены превращаются в витражи."}, {"q": "Кто написал икону «Троица»?", "o": ["Феофан Грек", "Дионисий", "Андрей Рублёв", "Симон Ушаков"], "a": 2, "e": "Андрей Рублёв, начало XV века."}, {"q": "Какой художник предвестил Возрождение, вернув фигурам объём и эмоции?", "o": ["Джотто", "Рембрандт", "Ван Эйк", "Боттичелли"], "a": 0, "e": "Джотто работал около 1300 года — за век до расцвета Ренессанса."}]}, {"id": "a4", "title": "Возрождение", "period": "XV — XVI век", "intro": ["Ренессанс начался в Италии, во Флоренции. Художники «возрождали» античность: изучали древние статуи, анатомию, математику. В центре мира снова оказался человек — это называется гуманизм.", "Открыта линейная перспектива, картина стала «окном в мир». Леонардо придумал сфумато — дымку, смягчающую контуры. Микеланджело создал титанических героев, Рафаэль — образ идеальной гармонии. Эти трое — титаны Высокого Возрождения.", "На севере Европы (Нидерланды, Германия) развилось своё Возрождение: Ян ван Эйк довёл масляную живопись до невероятной детальности, Дюрер прославился гравюрами."], "traits": ["Гуманизм: человек в центре мира", "Линейная перспектива и анатомическая точность", "Античные сюжеты наравне с библейскими", "Сфумато, масляная живопись", "Титаны: Леонардо, Микеланджело, Рафаэль"], "works": [{"t": "Рождение Венеры", "a": "Сандро Боттичелли", "y": "около 1485", "d": "Языческая богиня выходит из моря на раковине. Для христианской Флоренции — смелый жест. Линии плавные, как в танце.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg", "lic": "Public domain", "by": "Sandro Botticelli", "src": "media/img/d1f4f16c8b-1000.webp", "w": 1000, "h": 628, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg/1280px-Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Мона Лиза (Джоконда)", "a": "Леонардо да Винчи", "y": "1503–1519", "d": "Самая известная картина мира. Обратите внимание на сфумато: уголки губ и глаз растворены в дымке, поэтому улыбка «ускользает».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Mona_Lisa,_by_Leonardo_da_Vinci,_from_C2RMF_retouched.jpg", "lic": "Public domain", "by": "Leonardo da Vinci", "src": "media/img/b6403bc945-1000.webp", "w": 1000, "h": 1490, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg/1280px-Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Сотворение Адама", "a": "Микеланджело Буонарроти", "y": "около 1511", "d": "Фреска потолка Сикстинской капеллы. Пальцы Бога и Адама почти касаются — в этом зазоре вся драма.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Michelangelo_-_Creation_of_Adam_(cropped).jpg", "lic": "Public domain", "by": "Michelangelo", "src": "media/img/9cda9ecdae-1000.webp", "w": 1000, "h": 454, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Michelangelo_-_Creation_of_Adam_%28cropped%29.jpg/1280px-Michelangelo_-_Creation_of_Adam_%28cropped%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Афинская школа", "a": "Рафаэль Санти", "y": "1509–1511", "d": "Платон и Аристотель в центре, вокруг — великие мыслители. Идеальная перспектива: все линии сходятся к двум философам.", "img": {"page": "https://commons.wikimedia.org/wiki/File:%22The_School_of_Athens%22_by_Raffaello_Sanzio_da_Urbino.jpg", "lic": "Public domain", "by": "Raphael", "src": "media/img/88562caed1-1000.webp", "w": 1000, "h": 776, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/%22The_School_of_Athens%22_by_Raffaello_Sanzio_da_Urbino.jpg/1280px-%22The_School_of_Athens%22_by_Raffaello_Sanzio_da_Urbino.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Портрет четы Арнольфини", "a": "Ян ван Эйк", "y": "1434", "d": "Северное Возрождение. В выпуклом зеркале на стене отражена вся комната и сам художник.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Van_Eyck_-_Arnolfini_Portrait.jpg", "lic": "Public domain", "by": "Jan van Eyck", "src": "media/img/fc05e7255e-1000.webp", "w": 1000, "h": 1368, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Van_Eyck_-_Arnolfini_Portrait.jpg/1280px-Van_Eyck_-_Arnolfini_Portrait.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Давид", "a": "Микеланджело Буонарроти", "y": "1501–1504", "d": "Пятиметровый мраморный юноша перед боем с Голиафом. Классический контрапост — привет от Греции.", "img": {"page": "https://commons.wikimedia.org/wiki/File:%27David%27_by_Michelangelo_Fir_JBU004.jpg", "lic": "CC BY 3.0", "by": "Jörg Bittner Unna", "src": "media/img/36bbc1e88e-1000.webp", "w": 1000, "h": 1500, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/%27David%27_by_Michelangelo_Fir_JBU004.jpg/1280px-%27David%27_by_Michelangelo_Fir_JBU004.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}], "quiz": [{"q": "Что такое гуманизм?", "o": ["Вера в магию", "Взгляд, ставящий человека в центр мира", "Стиль архитектуры", "Техника фрески"], "a": 1, "e": "Гуманисты верили в достоинство и возможности человека."}, {"q": "Как называется дымчатая манера Леонардо, смягчающая контуры?", "o": ["Сфумато", "Импасто", "Пуантилизм", "Гризайль"], "a": 0, "e": "Sfumato — «исчезающий как дым»."}, {"q": "В каком городе началось итальянское Возрождение?", "o": ["Рим", "Венеция", "Флоренция", "Милан"], "a": 2, "e": "Флоренция при Медичи — колыбель Ренессанса."}, {"q": "Кто из этих художников — представитель Северного Возрождения?", "o": ["Рафаэль", "Ян ван Эйк", "Боттичелли", "Тициан"], "a": 1, "e": "Ван Эйк работал во Фландрии и прославился масляной живописью."}]}, {"id": "a5", "title": "Барокко", "period": "XVII век", "intro": ["Барокко — искусство страсти, движения и театрального эффекта. После спокойной гармонии Возрождения картины словно взрываются: диагонали, драматичный свет, напряжённые жесты.", "Караваджо выхватывает фигуры из темноты лучом света (тенебросо). Бернини заставляет мрамор кипеть. Рубенс пишет пышные тела и вихри. Рембрандт находит в свете и тени глубину человеческой души.", "В протестантской Голландии барокко тише: Вермеер и «малые голландцы» пишут уютные интерьеры, натюрморты и бытовые сцены для бюргерских домов."], "traits": ["Динамика, диагональные композиции", "Резкий контраст света и тени", "Театральность, пышность, эмоции на пределе", "Синтез искусств: архитектура + скульптура + живопись", "Голландия: бытовой жанр и натюрморт"], "works": [{"t": "Призвание апостола Матфея", "a": "Караваджо", "y": "1599–1600", "d": "Луч света следует за жестом Христа и падает на сборщика податей. Свет здесь — сам призыв.", "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Calling_of_Saint_Matthew-Caravaggo_(1599-1600).jpg", "lic": "Public domain", "by": "Caravaggio", "src": "media/img/0184cd4f33-1000.webp", "w": 1000, "h": 1028, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/The_Calling_of_Saint_Matthew-Caravaggo_%281599-1600%29.jpg/1280px-The_Calling_of_Saint_Matthew-Caravaggo_%281599-1600%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Ночной дозор", "a": "Рембрандт ван Рейн", "y": "1642", "d": "Групповой портрет стрелковой роты, превращённый в живую сцену. На самом деле действие дневное — картина потемнела от лака.", "img": {"page": "https://commons.wikimedia.org/wiki/File:La_ronda_de_noche,_por_Rembrandt_van_Rijn.jpg", "lic": "Public domain", "by": "Rembrandt", "src": "media/img/056817c627-1000.webp", "w": 1000, "h": 814, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/La_ronda_de_noche%2C_por_Rembrandt_van_Rijn.jpg/1280px-La_ronda_de_noche%2C_por_Rembrandt_van_Rijn.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Менины", "a": "Диего Веласкес", "y": "1656", "d": "Загадка-картина: художник пишет королевскую чету, отражённую в зеркале, а смотрим на сцену мы — с их места.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Las_Meninas,_by_Diego_Vel%C3%A1zquez,_from_Prado_in_Google_Earth.jpg", "lic": "Public domain", "by": "Diego Velázquez", "src": "media/img/394994c256-1000.webp", "w": 1000, "h": 1151, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Las_Meninas%2C_by_Diego_Vel%C3%A1zquez%2C_from_Prado_in_Google_Earth.jpg/1280px-Las_Meninas%2C_by_Diego_Vel%C3%A1zquez%2C_from_Prado_in_Google_Earth.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Девушка с жемчужной серёжкой", "a": "Ян Вермеер", "y": "около 1665", "d": "«Северная Мона Лиза». Тихий голландский свет, ультрамарин и один блик на жемчуге.", "img": {"page": "https://commons.wikimedia.org/wiki/File:1665_Girl_with_a_Pearl_Earring.jpg", "lic": "Public domain", "by": "Johannes Vermeer", "src": "media/img/1f01b6178c-1000.webp", "w": 1000, "h": 1184, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/1665_Girl_with_a_Pearl_Earring.jpg/1280px-1665_Girl_with_a_Pearl_Earring.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Экстаз святой Терезы", "a": "Джан Лоренцо Бернини", "y": "1647–1652", "d": "Скульптура как театральная сцена: мрамор превращён в облака и складки, сверху льётся настоящий свет из скрытого окна.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Ecstasy_of_Saint_Teresa_September_2015-2a.jpg", "lic": "CC BY-SA 4.0", "by": "Gian Lorenzo Bernini", "src": "media/img/ed744cd141-1000.webp", "w": 1000, "h": 1585, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Ecstasy_of_Saint_Teresa_September_2015-2a.jpg/1280px-Ecstasy_of_Saint_Teresa_September_2015-2a.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}], "quiz": [{"q": "Какой приём особенно характерен для Караваджо?", "o": ["Золотой фон", "Резкий луч света из темноты", "Пуантилизм", "Обратная перспектива"], "a": 1, "e": "Тенебросо — «тёмная манера»: фигуры вырваны из мрака светом."}, {"q": "Чем барокко отличается от Возрождения?", "o": ["Спокойствием и симметрией", "Движением, драмой, театральностью", "Плоскостью изображения", "Отказом от сюжета"], "a": 1, "e": "Возрождение — гармония, барокко — страсть и движение."}, {"q": "В какой стране работали Вермеер и Рембрандт?", "o": ["Испания", "Италия", "Голландия", "Франция"], "a": 2, "e": "Золотой век голландской живописи — XVII век."}]}, {"id": "a6", "title": "Классицизм и романтизм", "period": "XVIII — первая половина XIX века", "intro": ["Классицизм снова обращается к античности, но теперь ради морали: долг выше чувств, государство выше личного. Ясные линии, строгая композиция, герои как статуи. Лидер — Жак-Луи Давид.", "Романтизм — бунт против холодного разума. Романтики любят бурю, ночь, руины, экзотику, одиночество героя и свободу. Цвет становится горячим, мазок — свободным: Делакруа, Гойя, Каспар Давид Фридрих, Тёрнер.", "В России эпоху ярко представляют Карл Брюллов и Орест Кипренский, а пушкинская эпоха вся пронизана этими двумя стилями."], "traits": ["Классицизм: долг, разум, античные сюжеты, чёткий рисунок", "Романтизм: чувства, стихия, свобода, мистика", "Романтический герой одинок и противостоит миру", "Классицизм — линия, романтизм — цвет", "Интерес к национальной истории и фольклору"], "works": [{"t": "Клятва Горациев", "a": "Жак-Луи Давид", "y": "1784", "d": "Манифест классицизма: братья клянутся отцу сражаться за Рим. Мужчины — прямые линии долга, женщины справа — мягкие линии горя.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Jacques-Louis_David_-_Oath_of_the_Horatii_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Anne-Louis Girodet / After Jacques-Louis David", "src": "media/img/22bf98d9da-1000.webp", "w": 1000, "h": 780, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Jacques-Louis_David_-_Oath_of_the_Horatii_-_Google_Art_Project.jpg/1280px-Jacques-Louis_David_-_Oath_of_the_Horatii_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Свобода, ведущая народ", "a": "Эжен Делакруа", "y": "1830", "d": "Июльская революция в Париже. Аллегория Свободы с флагом идёт через баррикаду — символ Франции.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Eug%C3%A8ne_Delacroix_-_Le_28_Juillet._La_Libert%C3%A9_guidant_le_peuple.jpg", "lic": "Public domain", "by": "Eugène Delacroix", "src": "media/img/0c3bfae6f4-1000.webp", "w": 1000, "h": 802, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Eug%C3%A8ne_Delacroix_-_Le_28_Juillet._La_Libert%C3%A9_guidant_le_peuple.jpg/1280px-Eug%C3%A8ne_Delacroix_-_Le_28_Juillet._La_Libert%C3%A9_guidant_le_peuple.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Странник над морем тумана", "a": "Каспар Давид Фридрих", "y": "около 1818", "d": "Икона романтизма: одинокий человек спиной к нам перед бескрайней природой.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Caspar_David_Friedrich_-_Wanderer_above_the_sea_of_fog.jpg", "lic": "Public domain", "by": "Caspar David Friedrich", "src": "media/img/e5489bdc04-1000.webp", "w": 1000, "h": 1281, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b9/Caspar_David_Friedrich_-_Wanderer_above_the_sea_of_fog.jpg/1280px-Caspar_David_Friedrich_-_Wanderer_above_the_sea_of_fog.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Третье мая 1808 года", "a": "Франсиско Гойя", "y": "1814", "d": "Расстрел испанских повстанцев французами. Белая рубаха и раскинутые руки — образ жертвы на все времена.", "img": {"page": "https://commons.wikimedia.org/wiki/File:El_Tres_de_Mayo,_by_Francisco_de_Goya,_from_Prado_thin_black_margin.jpg", "lic": "Public domain", "by": "El_Tres_de_Mayo,_by_Francisco_de_Goya,_from_Prado_in_Google_Earth.jpg: Francisco", "src": "media/img/e92f790510-1000.webp", "w": 1000, "h": 772, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/El_Tres_de_Mayo%2C_by_Francisco_de_Goya%2C_from_Prado_thin_black_margin.jpg/1280px-El_Tres_de_Mayo%2C_by_Francisco_de_Goya%2C_from_Prado_thin_black_margin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Последний день Помпеи", "a": "Карл Брюллов", "y": "1830–1833", "d": "Первая русская картина с мировой славой. Классицистические фигуры в романтической катастрофе.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Karl_Brullov_-_The_Last_Day_of_Pompeii_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Karl Bryullov", "src": "media/img/7a055b23ec-1000.webp", "w": 1000, "h": 702, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Karl_Brullov_-_The_Last_Day_of_Pompeii_-_Google_Art_Project.jpg/1280px-Karl_Brullov_-_The_Last_Day_of_Pompeii_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}], "quiz": [{"q": "Что ставит на первое место классицизм?", "o": ["Личные чувства", "Долг и разум", "Мистику", "Впечатление момента"], "a": 1, "e": "Классицизм учит: долг перед обществом выше личного."}, {"q": "Какие темы любят романтики?", "o": ["Порядок и симметрию", "Стихию, свободу, одиночество героя", "Геометрические фигуры", "Повседневный быт"], "a": 1, "e": "Буря, ночь, горы, революция — всё, что сильнее разума."}, {"q": "Кто написал «Последний день Помпеи»?", "o": ["Илья Репин", "Карл Брюллов", "Иван Айвазовский", "Василий Суриков"], "a": 1, "e": "Карл Брюллов, 1833 год."}]}, {"id": "a7", "title": "Реализм и импрессионизм", "period": "вторая половина XIX века", "intro": ["Реалисты сказали: хватит богов и героев — пишем жизнь как есть. Крестьяне, рабочие, похороны в деревне. Во Франции это Курбе и Милле, в России — передвижники: Репин, Перов, Суриков, Левитан.", "Импрессионисты (от франц. impression — впечатление) пошли ещё дальше: вышли с мольбертами на улицу и стали ловить мгновение — свет, воздух, движение. Мазок стал быстрым и раздельным, чёрная краска почти исчезла.", "Название родилось из насмешки: критик увидел картину Моне «Впечатление. Восходящее солнце» на выставке 1874 года и обозвал всех «импрессионистами». Слово прижилось."], "traits": ["Реализм: правда жизни, социальные темы, простые люди", "Передвижники в России: Репин, Суриков, Перов, Левитан", "Импрессионизм: свет, воздух, мимолётное впечатление", "Живопись на пленэре (на открытом воздухе)", "Раздельный мазок, светлая палитра"], "works": [{"t": "Бурлаки на Волге", "a": "Илья Репин", "y": "1870–1873", "d": "Одиннадцать бурлаков тянут баржу. Каждый — отдельная судьба, а молодой Ларька в центре поднимает голову — будто бунтует.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Ilia_Efimovich_Repin_(1844-1930)_-_Volga_Boatmen_(1870-1873).jpg", "lic": "Public domain", "by": "Ilya Repin", "src": "media/img/8c2c6391f0-1000.webp", "w": 1000, "h": 462, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/Ilia_Efimovich_Repin_%281844-1930%29_-_Volga_Boatmen_%281870-1873%29.jpg/1280px-Ilia_Efimovich_Repin_%281844-1930%29_-_Volga_Boatmen_%281870-1873%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Впечатление. Восходящее солнце", "a": "Клод Моне", "y": "1872", "d": "Картина, давшая имя целому направлению. Порт Гавра в утренней дымке, оранжевое солнце из нескольких мазков.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Monet_-_Impression,_Sunrise.jpg", "lic": "Public domain", "by": "Claude Monet", "src": "media/img/d79ad960ff-1000.webp", "w": 1000, "h": 776, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Monet_-_Impression%2C_Sunrise.jpg/1280px-Monet_-_Impression%2C_Sunrise.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Бал в Мулен де ла Галетт", "a": "Пьер Огюст Ренуар", "y": "1876", "d": "Танцы на Монмартре. Солнечные пятна скользят по одежде и лицам — сама радость жизни.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Pierre-Auguste_Renoir,_Le_Moulin_de_la_Galette.jpg", "lic": "Public domain", "by": "Pierre-Auguste Renoir", "src": "media/img/4850d8c9de-1000.webp", "w": 1000, "h": 745, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Pierre-Auguste_Renoir%2C_Le_Moulin_de_la_Galette.jpg/1280px-Pierre-Auguste_Renoir%2C_Le_Moulin_de_la_Galette.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Над вечным покоем", "a": "Исаак Левитан", "y": "1894", "d": "Пейзаж настроения: маленькая церковь и кладбище над бескрайним простором. Левитан называл картину самой своей.", "img": {"page": "https://commons.wikimedia.org/wiki/File:LevitanAboveEternalPeace.jpg", "lic": "Public domain", "by": "Isaac Levitan", "src": "media/img/2a3260c8a1-1000.webp", "w": 1000, "h": 723, "remote": "https://upload.wikimedia.org/wikipedia/commons/0/08/LevitanAboveEternalPeace.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Голубые танцовщицы", "a": "Эдгар Дега", "y": "около 1897", "d": "Дега любил балет, но показывал его закулисье. Пастель, необычный ракурс — будто подсмотренный кадр.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Edgar_Degas_-_Blue_Dancers_(1898_Pushkin_Museum).jpg", "lic": "Public domain", "by": "Edgar Degas", "src": "media/img/5f2527d3eb-1000.webp", "w": 1000, "h": 983, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Edgar_Degas_-_Blue_Dancers_%281898_Pushkin_Museum%29.jpg/1280px-Edgar_Degas_-_Blue_Dancers_%281898_Pushkin_Museum%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}], "quiz": [{"q": "Откуда взялось слово «импрессионизм»?", "o": ["Из названия картины Моне «Впечатление»", "Из имени художника", "Из названия кафе", "Из манифеста Курбе"], "a": 0, "e": "«Impression, soleil levant» Моне, выставка 1874 года."}, {"q": "Как назывались русские реалисты, возившие выставки по стране?", "o": ["Мирискусники", "Передвижники", "Бубновалетовцы", "Символисты"], "a": 1, "e": "Товарищество передвижных художественных выставок, с 1870 года."}, {"q": "Что главное для импрессиониста?", "o": ["Мораль и долг", "Мгновенное впечатление: свет и воздух", "Геометрия формы", "Религиозный смысл"], "a": 1, "e": "Импрессионисты ловили мимолётное состояние природы."}]}, {"id": "a8", "title": "Постимпрессионизм и модерн", "period": "1880-е — 1910-е", "intro": ["Постимпрессионисты взяли у импрессионистов яркий цвет, но пошли каждый своим путём. Ван Гог — выразительный, вихревой мазок и чувства на пределе. Сезанн — строит природу из цилиндров, шаров и конусов (отсюда вырастет кубизм). Гоген — уезжает на Таити за первозданной простотой.", "Около 1900 года вся Европа увлеклась модерном (ар-нуво, югендстиль): плавные растительные линии, орнамент, золото. Климт в Вене, Муха в Париже.", "Мунк и символисты показывают уже не мир, а душу — тревогу, страх, сон. Отсюда один шаг до экспрессионизма XX века."], "traits": ["Ван Гог: экспрессивный мазок, яркий цвет", "Сезанн: геометрия формы — отец современного искусства", "Гоген: плоские яркие пятна, экзотика", "Модерн: плавные линии, орнамент, золото", "Символизм: сны, тревога, внутренний мир"], "works": [{"t": "Звёздная ночь", "a": "Винсент ван Гог", "y": "1889", "d": "Написана в лечебнице Сен-Реми. Небо закручено в вихри, кипарис взлетает пламенем — пейзаж души.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Van_Gogh_-_Starry_Night_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Vincent van Gogh", "src": "media/img/ffa8e3768f-1000.webp", "w": 1000, "h": 792, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Van_Gogh_-_Starry_Night_-_Google_Art_Project.jpg/1280px-Van_Gogh_-_Starry_Night_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Гора Сент-Виктуар", "a": "Поль Сезанн", "y": "около 1904", "d": "Сезанн писал эту гору десятки раз, строя пейзаж из цветовых плоскостей. Пикассо называл его «отцом всех нас».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Montagne_Sainte-Victoire,_par_Paul_C%C3%A9zanne_108.jpg", "lic": "Public domain", "by": "Paul Cézanne", "src": "media/img/2ed60c49d5-1000.webp", "w": 1000, "h": 794, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/Montagne_Sainte-Victoire%2C_par_Paul_C%C3%A9zanne_108.jpg/1280px-Montagne_Sainte-Victoire%2C_par_Paul_C%C3%A9zanne_108.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Откуда мы? Кто мы? Куда мы идём?", "a": "Поль Гоген", "y": "1897–1898", "d": "Таитянская притча о жизни: читается справа налево, от младенца до старости.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Paul_Gauguin_-_D%27ou_venons-nous.jpg", "lic": "Public domain", "by": "Paul Gauguin", "src": "media/img/42835591cb-1000.webp", "w": 1000, "h": 380, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/Paul_Gauguin_-_D%27ou_venons-nous.jpg/1280px-Paul_Gauguin_-_D%27ou_venons-nous.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Поцелуй", "a": "Густав Климт", "y": "1907–1908", "d": "«Золотой период» Климта: настоящее сусальное золото, мужской орнамент из прямоугольников, женский — из кругов.", "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Kiss_-_Gustav_Klimt_-_Google_Cultural_Institute.jpg", "lic": "Public domain", "by": "Gustav Klimt", "src": "media/img/1ff5535fac-1000.webp", "w": 1000, "h": 1003, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/The_Kiss_-_Gustav_Klimt_-_Google_Cultural_Institute.jpg/1280px-The_Kiss_-_Gustav_Klimt_-_Google_Cultural_Institute.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Крик", "a": "Эдвард Мунк", "y": "1893", "d": "Мунк описал миг, когда «почувствовал бесконечный крик природы». Символ тревоги нового века.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Edvard_Munch,_1893,_The_Scream,_oil,_tempera_and_pastel_on_cardboard,_91_x_73_cm,_National_Gallery_of_Norway.jpg", "lic": "Public domain", "by": "Edvard Munch", "src": "media/img/2119e6f136-1000.webp", "w": 1000, "h": 1241, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Edvard_Munch%2C_1893%2C_The_Scream%2C_oil%2C_tempera_and_pastel_on_cardboard%2C_91_x_73_cm%2C_National_Gallery_of_Norway.jpg/1280px-Edvard_Munch%2C_1893%2C_The_Scream%2C_oil%2C_tempera_and_pastel_on_cardboard%2C_91_x_73_cm%2C_National_Gallery_of_Norway.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}], "quiz": [{"q": "Кого называют «отцом современного искусства»?", "o": ["Моне", "Сезанна", "Ренуара", "Курбе"], "a": 1, "e": "Сезанн строил форму геометрически — из этого выросли кубизм и абстракция."}, {"q": "Какой стиль около 1900 года любил плавные растительные линии и орнамент?", "o": ["Барокко", "Модерн (ар-нуво)", "Кубизм", "Классицизм"], "a": 1, "e": "Модерн: Климт, Муха, Гауди, Шехтель."}, {"q": "Куда уехал Гоген в поисках первозданной жизни?", "o": ["В Японию", "На Таити", "В Египет", "В Россию"], "a": 1, "e": "Полинезия, Таити — его главные картины написаны там."}]}, {"id": "a9", "title": "Авангард XX века", "period": "1905 — 1930-е", "intro": ["Начало XX века — взрыв: художники отказываются изображать мир «как он выглядит». Фовисты (Матисс) освобождают цвет, кубисты (Пикассо, Брак) разбивают предмет на грани и показывают его со всех сторон сразу.", "Главное открытие эпохи — абстракция: картина может вообще ничего не изображать, как музыка. Первыми к ней пришли русские художники: Василий Кандинский и Казимир Малевич. «Чёрный квадрат» стал точкой отсчёта — «нулём форм».", "Дальше — сюрреализм (Дали, Магритт) с логикой сна, и Пит Мондриан с его решётками из чистых цветов. Многие произведения этих мастеров ещё охраняются авторским правом, поэтому здесь показаны те, что уже стали общественным достоянием."], "traits": ["Фовизм: «дикий» чистый цвет", "Кубизм: предмет разложен на грани", "Абстракция: картина без сюжета", "Русский авангард: Малевич (супрематизм), Кандинский", "Сюрреализм: логика сна и подсознания"], "works": [{"t": "Чёрный супрематический квадрат", "a": "Казимир Малевич", "y": "1915", "d": "Манифест супрематизма. На выставке 1915 года Малевич повесил его в «красный угол», где в русском доме висит икона.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Kazimir_Malevich,_1915,_Black_Suprematic_Square,_oil_on_linen_canvas,_79.5_x_79.5_cm,_Tretyakov_Gallery,_Moscow.jpg", "lic": "Public domain", "by": "Kazimir Malevich", "src": "media/img/2819ba4ed9-1000.webp", "w": 1000, "h": 1000, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Kazimir_Malevich%2C_1915%2C_Black_Suprematic_Square%2C_oil_on_linen_canvas%2C_79.5_x_79.5_cm%2C_Tretyakov_Gallery%2C_Moscow.jpg/1280px-Kazimir_Malevich%2C_1915%2C_Black_Suprematic_Square%2C_oil_on_linen_canvas%2C_79.5_x_79.5_cm%2C_Tretyakov_Gallery%2C_Moscow.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Композиция VII", "a": "Василий Кандинский", "y": "1913", "d": "Кандинский мыслил картину как симфонию: цвета звучат, линии играют мелодию. Одна из вершин ранней абстракции.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Vassily_Kandinsky,_1913_-_Composition_7.jpg", "lic": "Public domain", "by": "Wassily Kandinsky", "src": "media/img/c7747cc859-1000.webp", "w": 1000, "h": 657, "remote": "https://upload.wikimedia.org/wikipedia/commons/b/b4/Vassily_Kandinsky%2C_1913_-_Composition_7.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Композиция с красным, синим и жёлтым", "a": "Пит Мондриан", "y": "1930", "d": "Только прямые линии и три основных цвета. Стиль Мондриана потом разошёлся по дизайну, моде и архитектуре.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Piet_Mondriaan,_1930_-_Mondrian_Composition_II_in_Red,_Blue,_and_Yellow.jpg", "lic": "Public domain", "by": "Piet Mondrian", "src": "media/img/fe74d0d700-1000.webp", "w": 1000, "h": 1014, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Piet_Mondriaan%2C_1930_-_Mondrian_Composition_II_in_Red%2C_Blue%2C_and_Yellow.jpg/1280px-Piet_Mondriaan%2C_1930_-_Mondrian_Composition_II_in_Red%2C_Blue%2C_and_Yellow.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Красный конь (Купание красного коня)", "a": "Кузьма Петров-Водкин", "y": "1912", "d": "Конь цвета иконного киновари, сферическая перспектива. Современники видели в нём предчувствие судьбы России.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Bathing_of_a_Red_Horse_(Petrov-Vodkin).jpg", "lic": "Public domain", "by": "Kuzma Petrov-Vodkin", "src": "media/img/30ebf4db21-1000.webp", "w": 1000, "h": 880, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Bathing_of_a_Red_Horse_%28Petrov-Vodkin%29.jpg/1280px-Bathing_of_a_Red_Horse_%28Petrov-Vodkin%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}], "quiz": [{"q": "Как называется направление Малевича?", "o": ["Кубизм", "Супрематизм", "Фовизм", "Сюрреализм"], "a": 1, "e": "Супрематизм — от лат. supremus, «высший»: превосходство чистой формы и цвета."}, {"q": "Что такое абстракция?", "o": ["Портрет в профиль", "Живопись без изображения узнаваемых предметов", "Пейзаж ночью", "Копия античной статуи"], "a": 1, "e": "Абстракция говорит формой и цветом, как музыка звуком."}, {"q": "Кубисты…", "o": ["Писали только кубы", "Раскладывали предмет на грани, показывая с разных сторон", "Писали на пленэре", "Копировали иконы"], "a": 1, "e": "Пикассо и Брак показывали предмет одновременно с нескольких точек зрения."}]}], "music": [{"id": "m0", "title": "Как слушать музыку", "period": "Азбука", "intro": ["Музыка складывается из нескольких «кирпичиков». Мелодия — то, что можно напеть. Ритм — пульс и рисунок длительностей. Гармония — аккорды, на которых держится мелодия. Тембр — «окраска» звука: скрипку не спутаешь с трубой.", "Ещё важны темп (быстро или медленно), динамика (громко или тихо: форте и пиано) и лад. Мажор обычно звучит светло, минор — грустно или тревожно.", "Классическую музыку легче слушать, если знать её формы. Симфония — большое сочинение для оркестра из нескольких частей. Соната — то же для одного-двух инструментов. Концерт — солист соревнуется с оркестром. Опера — драма, где поют, а балет — где танцуют. Включите примеры ниже и попробуйте услышать разницу."], "traits": ["Мелодия, ритм, гармония, тембр", "Мажор — светло, минор — грустно", "Темп: адажио (медленно), аллегро (быстро), престо (очень быстро)", "Динамика: пиано (тихо), форте (громко)", "Формы: симфония, соната, концерт, опера, балет"], "works": [{"t": "Симфония № 5, часть 1", "a": "Людвиг ван Бетховен", "y": "1808", "d": "Четыре ноты «та-та-та-там» — самая узнаваемая тема в истории. Это мотив: короткая ячейка, из которой вырастает вся часть. Минор, аллегро, форте.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Ludwig_van_Beethoven_-_symphony_no._5_in_c_minor,_op._67_-_i._allegro_con_brio.ogg", "lic": "Public domain", "by": "Ludwig van Beethoven", "src": "media/audio/e4d31e8acd.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/e/e6/Ludwig_van_Beethoven_-_symphony_no._5_in_c_minor%2C_op._67_-_i._allegro_con_brio.ogg/Ludwig_van_Beethoven_-_symphony_no._5_in_c_minor%2C_op._67_-_i._allegro_con_brio.ogg.mp3"}}, {"t": "Сюита для виолончели № 1, Прелюдия", "a": "Иоганн Себастьян Бах", "y": "около 1720", "d": "Один инструмент — и целый мир. Послушайте тембр виолончели: тёплый, близкий к человеческому голосу. Мажор.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Bach_-_Cello_Suite_no._1_in_G_major,_BWV_1007_-_I._Pr%C3%A9lude.ogg", "lic": "Public domain", "by": "Bach, Johann-Sebastian.", "src": "media/audio/dd1ea7ee35.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/9/9d/Bach_-_Cello_Suite_no._1_in_G_major%2C_BWV_1007_-_I._Pr%C3%A9lude.ogg/Bach_-_Cello_Suite_no._1_in_G_major%2C_BWV_1007_-_I._Pr%C3%A9lude.ogg.mp3"}}, {"t": "Полёт шмеля", "a": "Николай Римский-Корсаков", "y": "1900", "d": "Пример темпа «престо»: стремительные пассажи изображают жужжание. Это музыкальная звукопись.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Rimsky-Korsakov_-_flight_of_the_bumblebee.oga", "lic": "Public domain", "by": "Composition: Nikolai Rimsky-Korsakov. Performer: US Army Band", "src": "media/audio/0eeda89ef7.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/c/c0/Rimsky-Korsakov_-_flight_of_the_bumblebee.oga/Rimsky-Korsakov_-_flight_of_the_bumblebee.oga.mp3"}}], "quiz": [{"q": "Как называется «окраска» звука, по которой мы отличаем скрипку от трубы?", "o": ["Темп", "Тембр", "Ритм", "Лад"], "a": 1, "e": "Тембр — индивидуальный цвет звучания инструмента или голоса."}, {"q": "Что означает «аллегро»?", "o": ["Медленно", "Тихо", "Быстро, весело", "Громко"], "a": 2, "e": "Allegro — «весело», то есть скоро. Медленно — adagio."}, {"q": "Как называется крупное сочинение для оркестра из нескольких частей?", "o": ["Соната", "Симфония", "Романс", "Этюд"], "a": 1, "e": "Симфония — обычно четыре части. Соната — для одного-двух инструментов."}, {"q": "Какой лад чаще звучит светло и радостно?", "o": ["Минор", "Мажор", "Хроматика", "Пентатоника"], "a": 1, "e": "Мажор — светлый, минор — печальный или драматичный."}]}, {"id": "m1", "title": "Средневековье", "period": "V — XIV век", "intro": ["Самая древняя музыка Европы, дошедшая до нас в записи нот, — церковная. Григорианский хорал — одноголосное пение на латыни, без инструментов и без чёткого ритма. Оно плавное, как молитва, и звучит в храме будто из вечности.", "Именно монахи придумали нотную запись: Гвидо д’Ареццо около 1000 года дал нотам названия, от которых пошли наши «до-ре-ми».", "Постепенно к одному голосу добавился второй и третий — так родилась полифония (многоголосие). А за стенами монастырей пели трубадуры и менестрели: о любви, рыцарях и весне."], "traits": ["Григорианский хорал: одноголосие, латынь, без инструментов", "Музыка служит молитве", "Рождение нотной записи (Гвидо д’Ареццо)", "Рождение многоголосия (полифонии)", "Светская музыка трубадуров и менестрелей"], "works": [{"t": "Rorate caeli (григорианский хорал)", "a": "Анонимный церковный распев", "y": "Средние века", "d": "Адвентский распев «Кропите, небеса». Одна мелодическая линия, свободный ритм — так звучали храмы тысячу лет назад.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Rorate_Caeli_~_Gregorian_Chant.ogg", "lic": "CC BY-SA 4.0", "by": "Inritter", "src": "media/audio/f768d50581.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/f/f8/Rorate_Caeli_~_Gregorian_Chant.ogg/Rorate_Caeli_~_Gregorian_Chant.ogg.mp3"}}, {"t": "O frondens virga", "a": "Хильдегарда Бингенская", "y": "XII век", "d": "Хильдегарда — аббатиса, мистик, учёный и одна из первых композиторов, чьё имя мы знаем.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:O_frondens.ogg", "lic": "CC BY-SA 3.0", "by": "Hildegard of Bingen / user:Makemi", "src": "media/audio/f542345302.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/3/37/O_frondens.ogg/O_frondens.ogg.mp3"}}, {"t": "Sumer is icumen in («Лето пришло»)", "a": "Анонимный английский автор", "y": "около 1260", "d": "Один из древнейших светских канонов: голоса вступают по очереди с одной мелодией. Песня о весне и кукушке.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Sumer_Is_Icumen_In_(13th_century_English_round).ogg", "lic": "CC BY-SA 4.0", "by": "Brandtnight2000", "src": "media/audio/d409d413f1.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/0/06/Sumer_Is_Icumen_In_%2813th_century_English_round%29.ogg/Sumer_Is_Icumen_In_%2813th_century_English_round%29.ogg.mp3"}}], "quiz": [{"q": "Что такое григорианский хорал?", "o": ["Оркестровая симфония", "Одноголосное церковное пение на латыни", "Танец при дворе", "Опера на библейский сюжет"], "a": 1, "e": "Названо в честь папы Григория I."}, {"q": "Кто дал нотам названия, от которых произошли «до-ре-ми»?", "o": ["Бах", "Гвидо д’Ареццо", "Палестрина", "Моцарт"], "a": 1, "e": "Около 1000 года, по первым слогам строк гимна св. Иоанну."}, {"q": "Как называется многоголосие, где каждый голос ведёт свою мелодию?", "o": ["Монодия", "Полифония", "Гомофония", "Унисон"], "a": 1, "e": "Полифония — «много звуков»."}]}, {"id": "m2", "title": "Возрождение", "period": "XV — XVI век", "intro": ["Музыка Ренессанса — это прежде всего хоровая полифония удивительной чистоты. Несколько голосов сплетаются в ровную, прозрачную ткань, и ни один не главнее другого.", "Вершина церковной музыки — Джованни Пьерлуиджи да Палестрина. Легенда гласит, что его месса «спасла» многоголосие, когда церковь хотела его запретить: слова в ней звучат ясно.", "Светская музыка тоже расцвела: итальянские мадригалы о любви, лютневые песни, танцы. В конце эпохи Монтеверди сделает шаг к барокко — и создаст одну из первых опер."], "traits": ["Хоровая полифония a cappella (без инструментов)", "Равноправие голосов, мягкая гармония", "Месса и мотет — церковные жанры", "Мадригал — светская песня о любви", "Лютня — главный домашний инструмент"], "works": [{"t": "Vestiva i colli", "a": "Джованни Палестрина", "y": "1566", "d": "Светский мадригал церковного мастера. Голоса текут спокойно, без резких скачков — фирменная ясность Палестрины.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Palestrina_-_Vestiva_i_colli_-_Prima_parte.ogg", "lic": "CC BY 4.0", "by": "Palestrina", "src": "media/audio/4ca1e6fd73.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/d/de/Palestrina_-_Vestiva_i_colli_-_Prima_parte.ogg/Palestrina_-_Vestiva_i_colli_-_Prima_parte.ogg.mp3"}}, {"t": "Agnus Dei", "a": "Джованни Палестрина", "y": "XVI век", "d": "Часть мессы. Прислушайтесь: голоса вступают друг за другом, как волны.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Palestrina_Agnus_Dei_from_Missa_in_Festis_Apostolorum.ogg", "lic": "Public domain", "by": "Palestrina", "src": "media/audio/57adbf9b3d.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/c/c5/Palestrina_Agnus_Dei_from_Missa_in_Festis_Apostolorum.ogg/Palestrina_Agnus_Dei_from_Missa_in_Festis_Apostolorum.ogg.mp3"}}, {"t": "Greensleeves («Зелёные рукава»)", "a": "Английская народная песня", "y": "XVI век", "d": "Самая знаменитая мелодия елизаветинской Англии. Легенда приписывает её Генриху VIII.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Greensleeves_Correct_Melody.ogg", "lic": "Public domain", "by": "Traditional English folk song", "src": "media/audio/3ca8312013.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/20/Greensleeves_Correct_Melody.ogg/Greensleeves_Correct_Melody.ogg.mp3"}}, {"t": "Cruda Amarilli", "a": "Клаудио Монтеверди", "y": "1605", "d": "Поздний мадригал с острыми диссонансами — Монтеверди уже на пороге барокко.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Monteverdi_-_cruda_amarilli.ogg", "lic": "CC BY-SA 2.0", "by": "", "src": "media/audio/0b27d76300.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/b0/Monteverdi_-_cruda_amarilli.ogg/Monteverdi_-_cruda_amarilli.ogg.mp3"}}], "quiz": [{"q": "Что значит «a cappella»?", "o": ["С оркестром", "Пение без инструментального сопровождения", "Очень быстро", "Для органа"], "a": 1, "e": "Буквально «как в капелле» — только голоса."}, {"q": "Кто — главный мастер церковной полифонии Возрождения?", "o": ["Вивальди", "Палестрина", "Гайдн", "Шопен"], "a": 1, "e": "Палестрина, Рим, XVI век."}, {"q": "Мадригал — это…", "o": ["Церковная месса", "Светская многоголосная песня", "Танец", "Инструмент"], "a": 1, "e": "Мадригалы пели о любви и природе."}]}, {"id": "m3", "title": "Барокко", "period": "1600 — 1750", "intro": ["Эпоха барокко подарила миру оперу, концерт, сонату, ораторию и оркестр. Музыка стала эффектной, контрастной, полной украшений. Её фундамент — басо континуо: непрерывный бас, над которым строятся аккорды (часто играл клавесин).", "Три великих имени: Вивальди (Венеция) — мастер концерта, его «Времена года» знает каждый. Бах (Германия) — гений полифонии, фуги и органа. Гендель (Германия, Англия) — короли опер и ораторий, «Аллилуйя» из «Мессии».", "Узнать барокко на слух: постоянный ровный пульс, клавесин или орган, моторное движение, украшения-трели и игра контрастов громко/тихо, соло/все."], "traits": ["Рождение оперы (Монтеверди, 1607)", "Басо континуо, звучание клавесина и органа", "Концерт: солист против оркестра, контраст", "Фуга — вершина полифонии", "Бах, Вивальди, Гендель"], "works": [{"t": "Времена года: «Весна», 1 часть", "a": "Антонио Вивальди", "y": "1725", "d": "Программная музыка: скрипки щебечут как птицы, журчат ручьи, гремит гроза. К каждому концерту Вивальди написал сонет.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Vivaldi_-_Four_Seasons_1_Spring_mvt_1_Allegro_-_John_Harrison_violin.oga", "lic": "CC BY-SA 4.0", "by": "Antonio Vivaldi", "src": "media/audio/1608612918.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/f/ff/Vivaldi_-_Four_Seasons_1_Spring_mvt_1_Allegro_-_John_Harrison_violin.oga/Vivaldi_-_Four_Seasons_1_Spring_mvt_1_Allegro_-_John_Harrison_violin.oga.mp3"}}, {"t": "Токката и фуга ре минор", "a": "Иоганн Себастьян Бах", "y": "около 1704", "d": "Органная пьеса в оркестровой версии Стоковского (запись 1927 года). Грозное начало знакомо всем по кино.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:PDP-CH_-_Philadelphia_Orchestra,_Leopold_Stokowski_-_Toccata_and_Fugue_in_D_minor,_BWV_565_-_Bach_-_Hmv-d1428-5-0761.flac", "lic": "Public domain", "by": "", "src": "media/audio/9b14423118.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/20/PDP-CH_-_Philadelphia_Orchestra%2C_Leopold_Stokowski_-_Toccata_and_Fugue_in_D_minor%2C_BWV_565_-_Bach_-_Hmv-d1428-5-0761.flac/PDP-CH_-_Philadelphia_Orchestra%2C_Leopold_Stokowski_-_Toccata_and_Fugue_in_D_minor%2C_BWV_565_-_Bach_-_Hmv-d1428-5-0761.flac.mp3"}}, {"t": "Бранденбургский концерт № 3", "a": "Иоганн Себастьян Бах", "y": "1721", "d": "Ровный «моторный» пульс и переклички групп струнных — образец барочного концерта.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Bach_-_Brandenburg_Concerto_No._3_-_1._Allegro.ogg", "lic": "CC BY-SA 2.0", "by": "Johann Sebastian Bach", "src": "media/audio/23a0896ac5.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/b0/Bach_-_Brandenburg_Concerto_No._3_-_1._Allegro.ogg/Bach_-_Brandenburg_Concerto_No._3_-_1._Allegro.ogg.mp3"}}, {"t": "«Аллилуйя» из оратории «Мессия»", "a": "Георг Фридрих Гендель", "y": "1741", "d": "По традиции на этом хоре публика встаёт — говорят, так впервые сделал король Георг II.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Handel_-_messiah_-_44_hallelujah.ogg", "lic": "CC BY-SA 2.0", "by": "Composer: Georg Friedrich Händel; Performed by: MIT Concert Choir; Directed by W", "src": "media/audio/17b9907669.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/c/ce/Handel_-_messiah_-_44_hallelujah.ogg/Handel_-_messiah_-_44_hallelujah.ogg.mp3"}}, {"t": "Ария (Air)", "a": "Иоганн Себастьян Бах", "y": "около 1730", "d": "Из оркестровой сюиты № 3. Мелодия парит над шагающим басом — тем самым басо континуо.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Air_(Bach).ogg", "lic": "Public domain", "by": "", "src": "media/audio/2bcfaba4de.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/1/1e/Air_%28Bach%29.ogg/Air_%28Bach%29.ogg.mp3"}}], "quiz": [{"q": "Какой жанр родился в эпоху барокко?", "o": ["Симфоническая поэма", "Опера", "Джаз", "Мадригал"], "a": 1, "e": "Первая сохранившаяся великая опера — «Орфей» Монтеверди, 1607."}, {"q": "Кто написал «Времена года»?", "o": ["Бах", "Гендель", "Вивальди", "Моцарт"], "a": 2, "e": "Антонио Вивальди, «рыжий священник» из Венеции."}, {"q": "Какой инструмент — «голос» барокко, на нём часто играли басо континуо?", "o": ["Рояль", "Клавесин", "Саксофон", "Арфа"], "a": 1, "e": "Фортепиано появится позже, а в барокко звучали клавесин и орган."}, {"q": "Фуга — это…", "o": ["Танец", "Полифоническая пьеса, где тема проходит по очереди во всех голосах", "Песня без слов", "Оркестровое вступление к опере"], "a": 1, "e": "Бах — величайший мастер фуги."}]}, {"id": "m4", "title": "Венская классика", "period": "1750 — 1820", "intro": ["Классицизм в музыке — это ясность, баланс и красота формы. Вместо сложной полифонии барокко — понятная мелодия с аккомпанементом. Сложились главные формы: симфония, соната, струнный квартет, классический концерт.", "Центр эпохи — Вена, и три её героя: Гайдн («отец симфонии», написал их больше ста), Моцарт (гений, писавший с детства во всех жанрах) и Бетховен (превратил музыку в драму и борьбу — мост к романтизму).", "На смену клавесину пришло фортепиано: оно умеет играть и тихо, и громко (отсюда название). Оркестр стал больше и разнообразнее."], "traits": ["Ясная мелодия + аккомпанемент", "Сонатная форма: экспозиция, разработка, реприза", "Симфония из четырёх частей", "Фортепиано вытесняет клавесин", "Гайдн, Моцарт, Бетховен"], "works": [{"t": "Маленькая ночная серенада, 1 часть", "a": "Вольфганг Амадей Моцарт", "y": "1787", "d": "Эталон классической ясности: изящные фразы, симметрия, лёгкость.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Mozart_-_Eine_kleine_Nachtmusik_-_1._Allegro.ogg", "lic": "CC BY-SA 2.0", "by": "Wolfgang Amadeus Mozart", "src": "media/audio/1d88e5c0b6.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/24/Mozart_-_Eine_kleine_Nachtmusik_-_1._Allegro.ogg/Mozart_-_Eine_kleine_Nachtmusik_-_1._Allegro.ogg.mp3"}}, {"t": "Турецкий марш (Рондо в турецком стиле)", "a": "Вольфганг Амадей Моцарт", "y": "1783", "d": "Финал фортепианной сонаты. В Вене тогда была мода на «янычарскую» музыку.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Mozart_-_Piano_Sonata_No._11_in_A_major_-_III._Allegro_(Turkish_March).ogg", "lic": "CC BY-SA 3.0 de", "by": "Bernd Krueger", "src": "media/audio/512a2dd145.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/bf/Mozart_-_Piano_Sonata_No._11_in_A_major_-_III._Allegro_%28Turkish_March%29.ogg/Mozart_-_Piano_Sonata_No._11_in_A_major_-_III._Allegro_%28Turkish_March%29.ogg.mp3"}}, {"t": "Симфония № 94 «Сюрприз», 2 часть", "a": "Йозеф Гайдн", "y": "1791", "d": "Тихая простая тема — и вдруг удар всего оркестра. Говорят, Гайдн хотел разбудить задремавшую публику.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Haydn;_Symphony_No._94_%22Surprise%22,_2._Andante.ogg", "lic": "Public domain", "by": "Boston Symphony Orchestra\n\nSerge Koussevitzky", "src": "media/audio/0ce9b31532.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/4/42/Haydn%3B_Symphony_No._94_%22Surprise%22%2C_2._Andante.ogg/Haydn%3B_Symphony_No._94_%22Surprise%22%2C_2._Andante.ogg.mp3"}}, {"t": "Реквием: Lacrimosa", "a": "Вольфганг Амадей Моцарт", "y": "1791", "d": "Последнее, над чем работал Моцарт: он умер, успев написать лишь восемь тактов «Лакримозы».", "audio": {"page": "https://commons.wikimedia.org/wiki/File:W._A._Mozart_-_Requiem_-_8._Lacrimosa_(Herbert_von_Karajan,_Wiener_Philharmoniker,_Wiener_Singverein,_1960).ogg", "lic": "Public domain", "by": "Wolfgang Amadeus Mozart", "src": "media/audio/a15c6d3970.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/0/04/W._A._Mozart_-_Requiem_-_8._Lacrimosa_%28Herbert_von_Karajan%2C_Wiener_Philharmoniker%2C_Wiener_Singverein%2C_1960%29.ogg/W._A._Mozart_-_Requiem_-_8._Lacrimosa_%28Herbert_von_Karajan%2C_Wiener_Philharmoniker%2C_Wiener_Singverein%2C_1960%29.ogg.mp3"}}, {"t": "«Лунная» соната, 3 часть", "a": "Людвиг ван Бетховен", "y": "1801", "d": "После знаменитой тихой первой части — буря. У Бетховена классическая форма наполняется страстью.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Beethoven_Moonlight_3rd_movement.ogg", "lic": "CC BY-SA 2.0 de", "by": "Ludwig van Beethoven", "src": "media/audio/01c1914487.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/d/d4/Beethoven_Moonlight_3rd_movement.ogg/Beethoven_Moonlight_3rd_movement.ogg.mp3"}}], "quiz": [{"q": "Кого называют «отцом симфонии»?", "o": ["Моцарта", "Бетховена", "Гайдна", "Баха"], "a": 2, "e": "Гайдн написал 104 симфонии и закрепил её форму."}, {"q": "Какой инструмент пришёл на смену клавесину в эпоху классицизма?", "o": ["Орган", "Фортепиано", "Гитара", "Арфа"], "a": 1, "e": "Pianoforte — «тихо-громко»: удар молоточка зависит от силы нажатия."}, {"q": "Какой город — столица венской классики?", "o": ["Париж", "Вена", "Лейпциг", "Рим"], "a": 1, "e": "Все трое — Гайдн, Моцарт, Бетховен — работали в Вене."}, {"q": "Чьё творчество стало мостом от классицизма к романтизму?", "o": ["Гайдна", "Бетховена", "Вивальди", "Палестрины"], "a": 1, "e": "Бетховен — классик по форме, романтик по силе чувства."}]}, {"id": "m5", "title": "Романтизм", "period": "1820 — 1900", "intro": ["Романтики сделали музыку языком чувств. Главное — выражение личности, любви, тоски, природы, мечты. Мелодии стали длинными и певучими, гармония — смелой и красочной, оркестр — огромным.", "Расцвели миниатюры: песня (Шуберт написал их более 600), фортепианные ноктюрны и вальсы Шопена. Появился культ виртуоза — Лист и Паганини сводили публику с ума. Композиторы обращаются к фольклору своих стран: Григ в Норвегии, Дворжак в Чехии.", "В опере два гиганта: Верди в Италии и Вагнер в Германии. Вагнер мечтал о «синтезе искусств» и придумал лейтмотив — музыкальную тему-«визитку» героя."], "traits": ["Музыка как исповедь души", "Миниатюры: песня, ноктюрн, вальс, прелюдия", "Виртуозы: Лист, Паганини", "Национальные школы и фольклор", "Опера: Верди и Вагнер, лейтмотив"], "works": [{"t": "Ноктюрн ми-бемоль мажор, соч. 9 № 2", "a": "Фредерик Шопен", "y": "1832", "d": "Ноктюрн — «ночная» пьеса. Мелодия поёт как голос оперной певицы, а левая рука мягко покачивает аккомпанемент.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Chopin_Nocturne_Op_9_No_2.ogg", "lic": "CC BY-SA 3.0", "by": "Beeswaxcandle at English Wikisource and Londonjackbooks at English Wikisource", "src": "media/audio/bd368afbec.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/f/fd/Chopin_Nocturne_Op_9_No_2.ogg/Chopin_Nocturne_Op_9_No_2.ogg.mp3"}}, {"t": "Ave Maria (Третья песня Эллен)", "a": "Франц Шуберт", "y": "1825", "d": "Песня на стихи Вальтера Скотта стала одной из самых любимых мелодий мира.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Franz_Schubert_-_Ellens_dritter_Gesang.oga", "lic": "CC BY 3.0", "by": "Composed by Franz Schubert", "src": "media/audio/564b062750.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/6/6f/Franz_Schubert_-_Ellens_dritter_Gesang.oga/Franz_Schubert_-_Ellens_dritter_Gesang.oga.mp3"}}, {"t": "Венгерская рапсодия № 2", "a": "Ференц Лист", "y": "1847", "d": "Медленное вступление и огненный пляс. Лист — величайший пианист-виртуоз своего века.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Franz_Liszt_-_Second_Hungarian_Rhapsody.ogg", "lic": "CC BY-SA 2.0", "by": "Franz Liszt", "src": "media/audio/5ef5468046.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/20/Franz_Liszt_-_Second_Hungarian_Rhapsody.ogg/Franz_Liszt_-_Second_Hungarian_Rhapsody.ogg.mp3"}}, {"t": "Полёт валькирий", "a": "Рихард Вагнер", "y": "1856", "d": "Из оперы «Валькирия». Девы-воительницы несутся над полем битвы — мощь вагнеровского оркестра.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Richard_Wagner_-_Ride_of_the_Valkyries.ogg", "lic": "Public domain", "by": "Richard Wagner (1813–1883)", "src": "media/audio/e260e0ce0d.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/29/Richard_Wagner_-_Ride_of_the_Valkyries.ogg/Richard_Wagner_-_Ride_of_the_Valkyries.ogg.mp3"}}, {"t": "В пещере горного короля", "a": "Эдвард Григ", "y": "1875", "d": "Из музыки к «Пер Гюнту». Одна тема повторяется всё быстрее и громче — классический пример крещендо.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Musopen_-_In_the_Hall_Of_The_Mountain_King.ogg", "lic": "Public domain", "by": "Grieg, Edvard; Musopen Symphony Orchestra", "src": "media/audio/84d933de2a.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/bb/Musopen_-_In_the_Hall_Of_The_Mountain_King.ogg/Musopen_-_In_the_Hall_Of_The_Mountain_King.ogg.mp3"}}, {"t": "La donna è mobile («Сердце красавицы»)", "a": "Джузеппе Верди", "y": "1851", "d": "Песенка Герцога из оперы «Риголетто». Наутро после премьеры её насвистывала вся Венеция.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:La_Donna_E_Mobile_Rigoletto.ogg", "lic": "Public domain", "by": "Giuseppe Verdi &amp; Francesco Maria Piave", "src": "media/audio/4a5afe39a8.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/5/5a/La_Donna_E_Mobile_Rigoletto.ogg/La_Donna_E_Mobile_Rigoletto.ogg.mp3"}}], "quiz": [{"q": "Что главное в музыке романтизма?", "o": ["Строгая форма", "Выражение чувств и личности", "Церковный канон", "Танцевальный ритм"], "a": 1, "e": "Романтики видели в музыке язык души."}, {"q": "Что такое лейтмотив?", "o": ["Финал оперы", "Повторяющаяся тема-характеристика героя или идеи", "Вид танца", "Музыкальный инструмент"], "a": 1, "e": "Вагнер построил на лейтмотивах свои огромные оперы."}, {"q": "Кто написал знаменитые ноктюрны и вальсы для фортепиано?", "o": ["Вагнер", "Шопен", "Верди", "Гайдн"], "a": 1, "e": "Фредерик Шопен — «поэт фортепиано»."}, {"q": "Как называется постепенное усиление громкости?", "o": ["Диминуэндо", "Крещендо", "Стаккато", "Легато"], "a": 1, "e": "Crescendo — «вырастая». Обратное — diminuendo."}]}, {"id": "m6", "title": "Русская классическая музыка", "period": "XIX — начало XX века", "intro": ["Русская композиторская школа родилась с Михаилом Глинкой — «отцом русской музыки». Его оперы «Жизнь за царя» и «Руслан и Людмила» соединили европейское мастерство с русской песней.", "Дальше — «Могучая кучка»: Балакирев, Мусоргский, Бородин, Римский-Корсаков, Кюи. Их цель — национальная музыка: сказки, история, народные интонации. А Пётр Чайковский стал самым любимым русским композитором в мире: балеты «Лебединое озеро», «Щелкунчик», «Спящая красавица», шесть симфоний, оперы.", "На рубеже веков — Рахманинов с его колокольными аккордами и огромными мелодиями, Скрябин с мечтой о цвето-музыке и юный Стравинский, взорвавший Париж «Весной священной»."], "traits": ["Глинка — основоположник русской классической музыки", "«Могучая кучка»: национальные сюжеты и фольклор", "Чайковский: лирика, балет, симфония", "Колокольность, протяжная песенность", "Рахманинов, Скрябин, Стравинский"], "works": [{"t": "Лебединое озеро (фрагмент из 2 акта)", "a": "Пётр Чайковский", "y": "1876", "d": "Тема лебедей — гобой поверх дрожащих струнных. Один из самых узнаваемых мотивов в истории балета.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Peter_Ilyich_Tchaikovsky-_Swan_Lake-_Extract_from_Act_2.ogg", "lic": "Public domain", "by": "Ballet Francaise Symphony Orchestra", "src": "media/audio/ca22213b07.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/2b/Peter_Ilyich_Tchaikovsky-_Swan_Lake-_Extract_from_Act_2.ogg/Peter_Ilyich_Tchaikovsky-_Swan_Lake-_Extract_from_Act_2.ogg.mp3"}}, {"t": "Танец Феи Драже («Щелкунчик»)", "a": "Пётр Чайковский", "y": "1892", "d": "Чайковский первым в России использовал челесту — инструмент со звуком «хрустальных капель».", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Tchaikovsky_-_Dance_of_the_Sugar_Plum_Fairy_-_The_Nutcracker.ogg", "lic": "CC BY 3.0", "by": "Pyotr Ilyich Tchaikovsky", "src": "media/audio/93dc198ebb.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/9/9d/Tchaikovsky_-_Dance_of_the_Sugar_Plum_Fairy_-_The_Nutcracker.ogg/Tchaikovsky_-_Dance_of_the_Sugar_Plum_Fairy_-_The_Nutcracker.ogg.mp3"}}, {"t": "Картинки с выставки: Прогулка", "a": "Модест Мусоргский", "y": "1874", "d": "Цикл о прогулке по выставке друга-художника Гартмана. «Прогулка» — сам композитор, переходящий от картины к картине.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Modest_Mussorgsky_-_pictures_at_an_exhibition_-_promenade_-_moderato_comodo_e_con_delicatezza.ogg", "lic": "Public domain", "by": "Modest Petrovich Mussorgsky", "src": "media/audio/ec87b265b5.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/d/df/Modest_Mussorgsky_-_pictures_at_an_exhibition_-_promenade_-_moderato_comodo_e_con_delicatezza.ogg/Modest_Mussorgsky_-_pictures_at_an_exhibition_-_promenade_-_moderato_comodo_e_con_delicatezza.ogg.mp3"}}, {"t": "Полёт шмеля", "a": "Николай Римский-Корсаков", "y": "1900", "d": "Из оперы «Сказка о царе Салтане» по Пушкину: князь Гвидон, обернувшись шмелём, летит к отцу.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Nikolai_Rimsky-Korsakov_-_Bumblebee.ogg", "lic": "CC BY-SA 2.0", "by": "Pianists: Neal and Nancy O'Doan", "src": "media/audio/7d45ebcdf2.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/a/ad/Nikolai_Rimsky-Korsakov_-_Bumblebee.ogg/Nikolai_Rimsky-Korsakov_-_Bumblebee.ogg.mp3"}}, {"t": "Прелюдия до-диез минор", "a": "Сергей Рахманинов (играет автор)", "y": "1892", "d": "Редкая историческая запись: играет сам Рахманинов. Три тяжёлых «колокольных» удара открывают пьесу.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Sergei_Rachmaninoff_performs_Rachmaninoff%27s_Prelude_in_C_sharp_minor,_Op._3.ogg", "lic": "Public domain", "by": "Sergei Rachmaninoff", "src": "media/audio/0afd6fd1cc.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/b9/Sergei_Rachmaninoff_performs_Rachmaninoff%27s_Prelude_in_C_sharp_minor%2C_Op._3.ogg/Sergei_Rachmaninoff_performs_Rachmaninoff%27s_Prelude_in_C_sharp_minor%2C_Op._3.ogg.mp3"}}, {"t": "Концерт для фортепиано № 1, 1 часть", "a": "Пётр Чайковский", "y": "1875", "d": "Мощные аккорды рояля на фоне величественной темы оркестра — одно из самых ярких вступлений в музыке.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Tchaikovsky,_Concerto_No.1_in_B-flat_minor_Op.23,_I._Allegro.ogg", "lic": "CC0", "by": "Pyotr Ilyich Tchaikovsky", "src": "media/audio/2b98fc1938.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/4/48/Tchaikovsky%2C_Concerto_No.1_in_B-flat_minor_Op.23%2C_I._Allegro.ogg/Tchaikovsky%2C_Concerto_No.1_in_B-flat_minor_Op.23%2C_I._Allegro.ogg.mp3"}}], "quiz": [{"q": "Кого называют «отцом русской музыки»?", "o": ["Чайковского", "Глинку", "Мусоргского", "Рахманинова"], "a": 1, "e": "Михаил Глинка, оперы «Жизнь за царя» (1836) и «Руслан и Людмила» (1842)."}, {"q": "Кто НЕ входил в «Могучую кучку»?", "o": ["Мусоргский", "Бородин", "Чайковский", "Римский-Корсаков"], "a": 2, "e": "Чайковский дружил с «кучкистами», но шёл своим путём."}, {"q": "Из какой оперы «Полёт шмеля»?", "o": ["«Садко»", "«Сказка о царе Салтане»", "«Снегурочка»", "«Золотой петушок»"], "a": 1, "e": "Римский-Корсаков, опера по сказке Пушкина, 1900."}, {"q": "Какой балет НЕ принадлежит Чайковскому?", "o": ["«Лебединое озеро»", "«Щелкунчик»", "«Спящая красавица»", "«Жар-птица»"], "a": 3, "e": "«Жар-птица» — балет Стравинского (1910)."}]}, {"id": "m7", "title": "Импрессионизм и новая музыка", "period": "1890 — 1930", "intro": ["Как художники-импрессионисты ловили свет, так Клод Дебюсси ловил в музыке настроения, отблески, туман и воду. Звуки размыты, аккорды «плывут», форма свободна. Рядом — Морис Равель, мастер изысканного оркестра, и чудак Эрик Сати с его простыми и странными пьесами.", "XX век разрушает правила: Стравинский играет с острым ритмом, Шёнберг отказывается от тональности. Музыка становится разнообразной как никогда.", "А в США в это время рождается совершенно новый мир — регтайм, блюз и джаз. Им посвящена следующая глава."], "traits": ["Импрессионизм: краски, настроение, размытость", "Дебюсси, Равель, Сати", "Необычные лады и «плывущие» аккорды", "XX век: эксперименты с ритмом и тональностью", "Стравинский, Шёнберг, Прокофьев, Шостакович"], "works": [{"t": "Лунный свет (Clair de lune)", "a": "Клод Дебюсси", "y": "1905", "d": "Из «Бергамасской сюиты». Тихая, мерцающая музыка — как лунный свет на воде.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Clair_de_lune_(Claude_Debussy)_Suite_bergamasque.ogg", "lic": "Public domain", "by": "Claude Debussy", "src": "media/audio/bbacfbab82.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/be/Clair_de_lune_%28Claude_Debussy%29_Suite_bergamasque.ogg/Clair_de_lune_%28Claude_Debussy%29_Suite_bergamasque.ogg.mp3"}}, {"t": "Гимнопедия № 1", "a": "Эрик Сати", "y": "1888", "d": "Медленная, прозрачная, почти неподвижная музыка. Сати предвосхитил минимализм и «фоновую» музыку XX века.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Satie_Gymnopedie_No_1_performed_by_Michael_Laucke.flac", "lic": "Public domain", "by": "Mlaucke", "src": "media/audio/92a127ed15.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/a/a6/Satie_Gymnopedie_No_1_performed_by_Michael_Laucke.flac/Satie_Gymnopedie_No_1_performed_by_Michael_Laucke.flac.mp3"}}, {"t": "Болеро", "a": "Морис Равель", "y": "1928", "d": "Одна мелодия и неизменный ритм барабана 15 минут — но каждый раз в новом тембре и всё громче. Урок оркестровки.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Bolero-Maurice_Ravel-1930.ogg", "lic": "Public domain", "by": "Maurice Ravel", "src": "media/audio/0cd80089af.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/c/c3/Bolero-Maurice_Ravel-1930.ogg/Bolero-Maurice_Ravel-1930.ogg.mp3"}}, {"t": "Жар-птица: Поганый пляс Кащея", "a": "Игорь Стравинский", "y": "1910", "d": "Балет для «Русских сезонов» Дягилева. Резкие акценты и дикий ритм — новая музыка XX века.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Infernal_Dance_from_The_Firebird_by_Stravinsky.ogg", "lic": "Public domain", "by": "", "src": "media/audio/36bce0b1a3.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/a/ab/Infernal_Dance_from_The_Firebird_by_Stravinsky.ogg/Infernal_Dance_from_The_Firebird_by_Stravinsky.ogg.mp3"}}], "quiz": [{"q": "Кто главный композитор-импрессионист?", "o": ["Вагнер", "Дебюсси", "Бетховен", "Гендель"], "a": 1, "e": "Клод Дебюсси, хотя сам он не любил этот ярлык."}, {"q": "В чём необычность «Болеро» Равеля?", "o": ["Оно без мелодии", "Одна тема и ритм повторяются, меняются тембр и громкость", "Его играют на одном рояле", "Оно длится 2 минуты"], "a": 1, "e": "Огромное крещендо на одной теме."}, {"q": "Для чьей антрепризы Стравинский написал «Жар-птицу»?", "o": ["Сергея Дягилева", "Петра Чайковского", "Мариуса Петипа", "Анны Павловой"], "a": 0, "e": "«Русские сезоны» Дягилева в Париже, 1910."}]}, {"id": "m8", "title": "Регтайм, блюз и джаз", "period": "1890-е — 1920-е", "intro": ["В конце XIX века на юге США из встречи африканских ритмов, церковных песнопений и европейской гармонии родились новые жанры. Регтайм — фортепианная музыка с «рваным» ритмом (синкопами). Король регтайма — Скотт Джоплин.", "Блюз — грустные песни с особыми «блюзовыми» нотами и формой из 12 тактов. Из регтайма и блюза в Новом Орлеане вырос джаз: импровизация, свинг, медные духовые.", "Первая джазовая пластинка вышла в 1917 году. А в 1924-м Джордж Гершвин соединил джаз с симфонией в «Рапсодии в стиле блюз». Отсюда пойдёт вся популярная музыка XX века — от свинга до рока."], "traits": ["Синкопа — смещённый, «рваный» акцент", "Регтайм: Скотт Джоплин", "Блюз: 12 тактов, блюзовые ноты", "Джаз: импровизация и свинг", "Новый Орлеан — колыбель джаза"], "works": [{"t": "Maple Leaf Rag («Регтайм кленового листа»)", "a": "Скотт Джоплин (играет автор, 1916)", "y": "1899", "d": "Самый известный регтайм. Левая рука шагает ровно, правая — синкопирует. Запись с перфоленты механического пианино, которую набил сам Джоплин.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Maple_Leaf_Rag_-_played_by_Scott_Joplin_1916_sample.ogg", "lic": "Public domain", "by": "Scott Joplin", "src": "media/audio/8857d3a7b4.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/e/e9/Maple_Leaf_Rag_-_played_by_Scott_Joplin_1916_sample.ogg/Maple_Leaf_Rag_-_played_by_Scott_Joplin_1916_sample.ogg.mp3"}}, {"t": "Livery Stable Blues", "a": "Original Dixieland Jass Band", "y": "1917", "d": "Первая в истории изданная джазовая пластинка. Кларнет, корнет и тромбон подражают животным на конюшне.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:ODJB_Livery_Stable_Blues_1917.ogg", "lic": "Public domain", "by": "Original Dixieland Jass Band (performer); Ray Lopez, Alcide Nunez (composers)", "src": "media/audio/9ef34d8c24.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/4/42/ODJB_Livery_Stable_Blues_1917.ogg/ODJB_Livery_Stable_Blues_1917.ogg.mp3"}}, {"t": "Рапсодия в стиле блюз", "a": "Джордж Гершвин (за роялем автор)", "y": "1924", "d": "Первая запись 1924 года. Знаменитое глиссандо кларнета в начале придумал музыкант оркестра на репетиции.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:1st_recording_of_Rhapsody_In_Blue_-_Paul_Whiteman_Orch._and_George_Gershwin_piano_(1924_version).ogg", "lic": "Public domain", "by": "George Gershwin and Paul Whiteman Orchestra", "src": "media/audio/3068c75e26.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/1/16/1st_recording_of_Rhapsody_In_Blue_-_Paul_Whiteman_Orch._and_George_Gershwin_piano_%281924_version%29.ogg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"}}], "quiz": [{"q": "Что такое синкопа?", "o": ["Медленный темп", "Смещение акцента на слабую долю", "Вид барабана", "Пение хором"], "a": 1, "e": "Синкопы делают ритм «рваным» и упругим — основа регтайма и джаза."}, {"q": "Кто «король регтайма»?", "o": ["Луи Армстронг", "Скотт Джоплин", "Джордж Гершвин", "Дюк Эллингтон"], "a": 1, "e": "Scott Joplin, «Maple Leaf Rag», 1899."}, {"q": "Какой город считают колыбелью джаза?", "o": ["Нью-Йорк", "Чикаго", "Новый Орлеан", "Лос-Анджелес"], "a": 2, "e": "New Orleans, конец XIX — начало XX века."}, {"q": "Что главное в джазе?", "o": ["Строгое следование нотам", "Импровизация и свинг", "Пение на латыни", "Отсутствие ритма"], "a": 1, "e": "Джазмен сочиняет прямо во время игры."}]}], "lit": [{"id": "l0", "title": "Как читать литературу", "period": "Азбука", "intro": ["Всю художественную литературу делят на три рода. Эпос рассказывает историю: роман, повесть, рассказ, поэма, басня. Лирика выражает чувства и мысли: стихотворение, элегия, ода. Драма разыгрывается на сцене: трагедия, комедия, драма.", "Стихи держатся на ритме. В русской поэзии главные размеры — ямб (та-ТА: «Мой дЯдя сАмых чЕстных прАвил») и хорей (ТА-та: «БУря мглОю нЕбо крОет»). Есть и трёхсложные: дактиль, амфибрахий, анапест.", "Писатели работают с тропами — образными приёмами. Эпитет — яркое определение («чудное мгновенье»). Метафора — скрытое сравнение («горит восток зарёю новой»). Олицетворение — неживое ведёт себя как живое. Узнайте эти приёмы, и тексты заиграют по-новому.", "Почти всю классику можно читать прямо здесь: тексты загружаются из Викитеки — свободной библиотеки, где лежат произведения, перешедшие в общественное достояние."], "traits": ["Три рода: эпос, лирика, драма", "Ямб (та-ТА) и хорей (ТА-та)", "Эпитет, метафора, сравнение, олицетворение", "Сюжет, композиция, герой, конфликт", "Классика — то, что перечитывают веками"], "works": [{"t": "Зимнее утро", "a": "Александр Пушкин", "y": "1829", "ws": "Зимнее утро (Пушкин)", "q": "Мороз и солнце; день чудесный!\nЕще ты дремлешь, друг прелестный —\nПора, красавица, проснись…", "d": "Лирика. Четырёхстопный ямб. Найдите эпитеты: «день чудесный», «друг прелестный».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Kiprensky_Pushkin.jpg", "lic": "Public domain", "by": "Orest Kiprensky", "src": "media/img/a9aa6bfcb8-360.webp", "w": 1000, "h": 1164, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Kiprensky_Pushkin.jpg/1280px-Kiprensky_Pushkin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Ворона и Лисица", "a": "Иван Крылов", "y": "1807", "ws": "Ворона и Лисица (Крылов)", "q": "Уж сколько раз твердили миру,\nЧто лесть гнусна, вредна; но только всё не впрок,\nИ в сердце льстец всегда отыщет уголок.", "d": "Басня — эпос в миниатюре: короткий рассказ с моралью. Крылов сделал её народным жанром.", "img": {"page": "https://commons.wikimedia.org/wiki/File:0521Fc._Portrait_of_I.A._Krylov,_1839_(Karl_Bryullov).jpg", "lic": "Public domain", "by": "Karl Bryullov", "src": "media/img/55eee36680-360.webp", "w": 1000, "h": 1208, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/0521Fc._Portrait_of_I.A._Krylov%2C_1839_%28Karl_Bryullov%29.jpg/1280px-0521Fc._Portrait_of_I.A._Krylov%2C_1839_%28Karl_Bryullov%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "К *** («Я помню чудное мгновенье…»)", "a": "Александр Пушкин", "y": "1825", "ws": "К *** («Я помню чудное мгновенье...») (Пушкин)", "q": "Я помню чудное мгновенье:\nПередо мной явилась ты,\nКак мимолетное виденье,\nКак гений чистой красоты.", "d": "Любовная лирика, посвящённая Анне Керн. Обратите внимание на сравнение «как мимолетное виденье».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Kiprensky_Pushkin.jpg", "lic": "Public domain", "by": "Orest Kiprensky", "src": "media/img/a9aa6bfcb8-360.webp", "w": 1000, "h": 1164, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Kiprensky_Pushkin.jpg/1280px-Kiprensky_Pushkin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}], "quiz": [{"q": "К какому роду литературы относится трагедия?", "o": ["Эпос", "Лирика", "Драма", "Басня"], "a": 2, "e": "Трагедия и комедия — жанры драмы, они пишутся для сцены."}, {"q": "Какой стихотворный размер: та-ТА, та-ТА?", "o": ["Хорей", "Ямб", "Дактиль", "Анапест"], "a": 1, "e": "Ямб — ударение на второй слог стопы. «Мой дЯдя сАмых чЕстных прАвил»."}, {"q": "«Чудное мгновенье» — это пример…", "o": ["Метафоры", "Эпитета", "Рифмы", "Гиперболы"], "a": 1, "e": "Эпитет — художественное определение."}, {"q": "Басня — это…", "o": ["Лирическое стихотворение", "Короткий поучительный рассказ с моралью", "Пьеса", "Роман в письмах"], "a": 1, "e": "Басни писали Эзоп, Лафонтен, Крылов."}]}, {"id": "l1", "title": "Античность", "period": "VIII век до н. э. — V век н. э.", "intro": ["Европейская литература начинается с Гомера. «Илиада» рассказывает о Троянской войне и гневе Ахиллеса, «Одиссея» — о десятилетнем возвращении Одиссея домой. Эти поэмы веками учили греков, что такое честь, хитрость, верность.", "Афины V века до н. э. подарили миру театр. Трагики Эсхил, Софокл и Еврипид писали о судьбе, вине и выборе, комедиограф Аристофан смеялся над политиками.", "Рим продолжил эстафету: Вергилий написал «Энеиду», Овидий — «Метаморфозы», сборник мифов о превращениях, из которого потом черпали художники всех веков."], "traits": ["Эпос: Гомер, «Илиада» и «Одиссея»", "Театр: трагедия и комедия", "Мифы как основа сюжетов", "Рок, судьба, катарсис", "Рим: Вергилий, Овидий, Гораций"], "works": [{"t": "Илиада", "a": "Гомер (перевод Н. Гнедича)", "y": "VIII век до н. э.", "ws": "Илиада (Гомер; Гнедич)", "q": "Гнев, богиня, воспой Ахиллеса, Пелеева сына,\nГрозный, который ахеянам тысячи бедствий соделал…", "d": "Пятьдесят дней десятого года Троянской войны. Перевод Гнедича писан гекзаметром — размером Гомера.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Homer_British_Museum.jpg", "lic": "Public domain", "by": "", "src": "media/img/fbefb57a99-360.webp", "w": 1000, "h": 1260, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/1c/Homer_British_Museum.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Одиссея", "a": "Гомер (перевод В. Жуковского)", "y": "VIII век до н. э.", "ws": "Одиссея (Гомер; Жуковский)", "q": "Муза, скажи мне о том многоопытном муже, который,\nСтранствуя долго со дня, как святой Илион им разрушен…", "d": "Циклоп, сирены, волшебница Цирцея — и верная Пенелопа, ждущая двадцать лет. Первый в мире «роман-путешествие».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Homer_British_Museum.jpg", "lic": "Public domain", "by": "", "src": "media/img/fbefb57a99-360.webp", "w": 1000, "h": 1260, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/1c/Homer_British_Museum.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Царь Эдип", "a": "Софокл", "y": "около 429 г. до н. э.", "ws": "Царь Эдип (Софокл; Зелинский)", "q": "", "d": "Эдип расследует убийство царя — и выясняет, что убийца он сам. Аристотель считал эту трагедию образцовой.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Sophocles_pushkin.jpg", "lic": "CC BY-SA 3.0", "by": "user:shakko", "src": "media/img/ffce1e9764-360.webp", "w": 1000, "h": 1358, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/19/Sophocles_pushkin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Метаморфозы", "a": "Овидий", "y": "8 г. н. э.", "ws": "Метаморфозы (Овидий)", "q": "", "d": "Около 250 мифов: Нарцисс, Эхо, Дедал и Икар, Орфей и Эвридика. Главная «шпаргалка» художников Возрождения и барокко."}], "quiz": [{"q": "О чём рассказывает «Илиада»?", "o": ["О странствиях Одиссея", "О Троянской войне и гневе Ахиллеса", "О сотворении мира", "О Риме"], "a": 1, "e": "Илион — другое название Трои."}, {"q": "Где родился европейский театр?", "o": ["В Риме", "В Афинах", "В Египте", "В Византии"], "a": 1, "e": "Афины, V век до н. э., праздники Диониса."}, {"q": "Что такое катарсис?", "o": ["Финальная битва", "Очищение души через сострадание и страх", "Вид стиха", "Хор в трагедии"], "a": 1, "e": "Так Аристотель описал действие трагедии на зрителя."}]}, {"id": "l2", "title": "Средневековье", "period": "V — XV век", "intro": ["Средневековая литература — это героический эпос, жития святых, рыцарские романы и летописи. У французов — «Песнь о Роланде», у немцев — «Песнь о Нибелунгах», у англичан — легенды о короле Артуре.", "На Руси главный памятник — «Слово о полку Игореве» (конец XII века): рассказ о неудачном походе князя Игоря на половцев и призыв князей к единству. Знаменит «Плач Ярославны».", "Вершина эпохи — «Божественная комедия» Данте (начало XIV века): путешествие поэта через Ад, Чистилище и Рай. Это и итог Средневековья, и первый шаг к Возрождению."], "traits": ["Героический эпос и рыцарский роман", "Религиозная литература, жития", "Древнерусская литература: летописи, «Слово»", "Аллегория и символ", "Данте — мост к Возрождению"], "works": [{"t": "Слово о полку Игореве", "a": "Неизвестный автор", "y": "конец XII века", "ws": "Слово о полку Игореве", "q": "Не лѣпо ли ны бяшетъ, братие, начяти старыми словесы трудныхъ повѣстий о пълку Игоревѣ, Игоря Святъславлича?", "d": "Поход 1185 года. Рукопись нашли в конце XVIII века, а в 1812 году она сгорела в московском пожаре."}, {"t": "Божественная комедия", "a": "Данте Алигьери (перевод Д. Мина)", "y": "1307–1321", "ws": "Божественная комедия (Данте; Мин)/ДО", "q": "Земную жизнь пройдя до половины,\nЯ очутился в сумрачном лесу…\n(перевод М. Лозинского)", "d": "Сто песен, девять кругов Ада. Проводник Данте — римский поэт Вергилий, а в Раю — возлюбленная Беатриче.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Portrait_de_Dante.jpg", "lic": "Public domain", "by": "Sandro Botticelli", "src": "media/img/03f2e287dc-360.webp", "w": 1000, "h": 1528, "remote": "https://upload.wikimedia.org/wikipedia/commons/6/6f/Portrait_de_Dante.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}], "quiz": [{"q": "О чём «Слово о полку Игореве»?", "o": ["О Куликовской битве", "О походе князя Игоря на половцев", "О крещении Руси", "О Ледовом побоище"], "a": 1, "e": "Поход 1185 года."}, {"q": "Кто ведёт Данте по Аду и Чистилищу?", "o": ["Гомер", "Вергилий", "Беатриче", "Овидий"], "a": 1, "e": "Вергилий, автор «Энеиды». В Раю его сменяет Беатриче."}, {"q": "Какой эпос — французский?", "o": ["«Песнь о Нибелунгах»", "«Песнь о Роланде»", "«Беовульф»", "«Калевала»"], "a": 1, "e": "«Песнь о Роланде», XI–XII век."}]}, {"id": "l3", "title": "Возрождение", "period": "XIV — начало XVII века", "intro": ["Гуманизм пришёл и в литературу. Петрарка написал сонеты к Лауре, Боккаччо — «Декамерон», сто живых и смешных новелл. Литература заговорила о земной любви и человеческой природе.", "Вершины позднего Возрождения — Шекспир и Сервантес (они умерли в один и тот же 1616 год). Шекспир создал «Гамлета», «Ромео и Джульетту», «Отелло», «Короля Лира», «Макбета» — героев, ставших архетипами. Сервантес написал «Дон Кихота» — первый великий роман Нового времени.", "Тургенев в знаменитой речи разделил людей на два типа: «Гамлеты» — сомневающиеся, и «Дон Кихоты» — верящие и действующие."], "traits": ["Гуманизм, земная любовь, личность", "Сонет: 14 строк (Петрарка, Шекспир)", "Новелла: Боккаччо", "Шекспир — вершина драмы", "Сервантес — рождение романа"], "works": [{"t": "Гамлет", "a": "Уильям Шекспир (перевод А. Кронеберга)", "y": "около 1600", "ws": "Гамлет (Шекспир; Кронеберг)", "q": "Быть или не быть — вот в чём вопрос.", "d": "Принц датский мстит за отца — и мучается сомнениями. Самая ставимая пьеса в мире.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Shakespeare.jpg", "lic": "Public domain", "by": "Attributed to John Taylor", "src": "media/img/91b93e3e9b-360.webp", "w": 1000, "h": 1275, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Shakespeare.jpg/1280px-Shakespeare.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Ромео и Джульетта", "a": "Уильям Шекспир", "y": "1595", "ws": "Ромео и Джульетта (Шекспир)", "q": "Нет повести печальнее на свете,\nЧем повесть о Ромео и Джульетте.\n(перевод Т. Щепкиной-Куперник)", "d": "Любовь детей враждующих семей Вероны. Из этой пьесы выросли балет Прокофьева и множество фильмов.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Shakespeare.jpg", "lic": "Public domain", "by": "Attributed to John Taylor", "src": "media/img/91b93e3e9b-360.webp", "w": 1000, "h": 1275, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Shakespeare.jpg/1280px-Shakespeare.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Дон Кихот", "a": "Мигель де Сервантес", "y": "1605–1615", "ws": "Дон Кихот Ламанчский (Сервантес)", "q": "", "d": "Бедный идальго начитался рыцарских романов и отправился совершать подвиги со своим оруженосцем Санчо Пансой. Пародия, ставшая трагедией идеалиста.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Cervantes_J%C3%A1uregui.jpg", "lic": "Public domain", "by": "Attributed to Juan de Jáuregui", "src": "media/img/444076cb72-360.webp", "w": 1000, "h": 1312, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Cervantes_J%C3%A1uregui.jpg/1280px-Cervantes_J%C3%A1uregui.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}], "quiz": [{"q": "Сколько строк в сонете?", "o": ["8", "12", "14", "16"], "a": 2, "e": "Сонет — 14 строк: Петрарка, Шекспир, Пушкин."}, {"q": "Кто написал «Дон Кихота»?", "o": ["Шекспир", "Сервантес", "Боккаччо", "Данте"], "a": 1, "e": "Мигель де Сервантес Сааведра."}, {"q": "Чьи слова «Быть или не быть»?", "o": ["Ромео", "Гамлета", "Макбета", "Отелло"], "a": 1, "e": "Монолог принца Гамлета, III акт."}]}, {"id": "l4", "title": "Классицизм и Просвещение", "period": "XVII — XVIII век", "intro": ["Классицизм в литературе — порядок и правила. Драма должна соблюдать три единства: места, времени и действия. Герои делятся на положительных и отрицательных, у них «говорящие» фамилии. Корнель и Расин писали трагедии, Мольер — комедии, высмеивающие пороки.", "XVIII век — эпоха Просвещения: вера в разум, науку и воспитание. Вольтер, Дидро, Руссо, Свифт («Путешествия Гулливера»). Гёте в Германии прошёл путь от бурных чувств к своему главному труду — «Фаусту».", "В России — Ломоносов, Державин, Фонвизин («Недоросль»). А в 1820-х Грибоедов в «Горе от ума» использует классицистические правила, но наполняет их живой современностью."], "traits": ["Правило трёх единств", "«Говорящие» фамилии, герои-маски", "Комедия высмеивает пороки (Мольер)", "Просвещение: вера в разум", "Гёте, Вольтер, Свифт, Фонвизин"], "works": [{"t": "Тартюф, или Обманщик", "a": "Мольер", "y": "1664", "ws": "Тартюф, или Обманщик (Мольер; Лихачёв)", "q": "", "d": "Лицемер-святоша втирается в доверие к богатому Оргону. Пьесу пять лет запрещали — церковь узнала себя.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Pierre_Mignard_-_Portrait_de_Jean-Baptiste_Poquelin_dit_Moli%C3%A8re_(1622-1673)_-_Google_Art_Project_(cropped).jpg", "lic": "Public domain", "by": "Pierre Mignard I", "src": "media/img/483bdcde10-360.webp", "w": 1000, "h": 1134, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/Pierre_Mignard_-_Portrait_de_Jean-Baptiste_Poquelin_dit_Moli%C3%A8re_%281622-1673%29_-_Google_Art_Project_%28cropped%29.jpg/1280px-Pierre_Mignard_-_Portrait_de_Jean-Baptiste_Poquelin_dit_Moli%C3%A8re_%281622-1673%29_-_Google_Art_Project_%28cropped%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Кандид, или Оптимизм", "a": "Вольтер", "y": "1759", "ws": "Кандид, или Оптимизм (Вольтер; Сологуб)", "q": "", "d": "Философская повесть: наивный Кандид проходит через войны и бедствия, но учитель твердит, что «всё к лучшему в этом лучшем из миров». Финал: «надо возделывать свой сад».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Atelier_de_Nicolas_de_Largilli%C3%A8re,_portrait_de_Voltaire,_d%C3%A9tail_(mus%C3%A9e_Carnavalet)_-002.jpg", "lic": "Public domain", "by": "Nicolas de Largillière", "src": "media/img/75f8d54fe1-360.webp", "w": 1000, "h": 1250, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Atelier_de_Nicolas_de_Largilli%C3%A8re%2C_portrait_de_Voltaire%2C_d%C3%A9tail_%28mus%C3%A9e_Carnavalet%29_-002.jpg/1280px-Atelier_de_Nicolas_de_Largilli%C3%A8re%2C_portrait_de_Voltaire%2C_d%C3%A9tail_%28mus%C3%A9e_Carnavalet%29_-002.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Фауст", "a": "Иоганн Вольфганг Гёте", "y": "1808–1832", "ws": "Фауст (Гёте)", "q": "Остановись, мгновенье, ты прекрасно!", "d": "Учёный продаёт душу Мефистофелю в обмен на мгновение полного счастья. Гёте писал «Фауста» почти 60 лет.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Goethe_(Stieler_1828).jpg", "lic": "Public domain", "by": "Joseph Karl Stieler", "src": "media/img/1b680922c8-360.webp", "w": 1000, "h": 1233, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Goethe_%28Stieler_1828%29.jpg/1280px-Goethe_%28Stieler_1828%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Горе от ума", "a": "Александр Грибоедов", "y": "1824", "ws": "Горе от ума (Грибоедов)", "q": "Карету мне, карету!", "d": "Чацкий возвращается в Москву и сталкивается с фамусовским обществом. Пушкин предсказал: половина стихов войдёт в пословицы. Так и вышло: «Счастливые часов не наблюдают»."}], "quiz": [{"q": "Что такое правило трёх единств?", "o": ["Три героя, три акта, три песни", "Единство места, времени и действия", "Три размера стиха", "Три рода литературы"], "a": 1, "e": "Действие пьесы — в одном месте, за сутки, с одной сюжетной линией."}, {"q": "Кому Фауст продаёт душу?", "o": ["Воланду", "Мефистофелю", "Люциферу", "Демону"], "a": 1, "e": "Мефистофель у Гёте — «часть силы той, что вечно хочет зла и вечно совершает благо»."}, {"q": "Кто главный герой «Горя от ума»?", "o": ["Онегин", "Чацкий", "Печорин", "Обломов"], "a": 1, "e": "Александр Андреевич Чацкий."}]}, {"id": "l5", "title": "Романтизм: от Байрона до Лермонтова", "period": "конец XVIII — середина XIX века", "intro": ["Романтики восстали против разума и правил. Их герой — одинокий бунтарь, изгнанник, мечтатель, в конфликте с обществом. Их темы — свобода, страсть, экзотика, природа, народные легенды, тайна.", "В Европе — Байрон (его «байронический герой» покорил всех), Вальтер Скотт (исторический роман), Гюго («Собор Парижской Богоматери»), Гофман, Эдгар По.", "В России романтизм начал Жуковский, его подхватили молодой Пушкин и Лермонтов. Но Пушкин быстро перерос романтизм: «Евгений Онегин» — уже реализм, «энциклопедия русской жизни» (Белинский). Лермонтов в «Герое нашего времени» создал первый русский психологический роман."], "traits": ["Романтический герой: одиночка и бунтарь", "Двоемирие: мечта против реальности", "Экзотика, история, фольклор", "Байрон, Гюго, Скотт, По", "Пушкин и Лермонтов — от романтизма к реализму"], "works": [{"t": "Евгений Онегин", "a": "Александр Пушкин", "y": "1823–1831", "ws": "Евгений Онегин (Пушкин)", "q": "Мой дядя самых честных правил,\nКогда не в шутку занемог,\nОн уважать себя заставил\nИ лучше выдумать не мог.", "d": "Роман в стихах. Пушкин придумал для него особую «онегинскую строфу» из 14 строк.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Kiprensky_Pushkin.jpg", "lic": "Public domain", "by": "Orest Kiprensky", "src": "media/img/a9aa6bfcb8-360.webp", "w": 1000, "h": 1164, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Kiprensky_Pushkin.jpg/1280px-Kiprensky_Pushkin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Капитанская дочка", "a": "Александр Пушкин", "y": "1836", "ws": "Капитанская дочка (Пушкин)", "q": "Береги честь смолоду.", "d": "Исторический роман о Пугачёвском бунте. Эпиграф — пословица, ставшая девизом героя Петра Гринёва.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Kiprensky_Pushkin.jpg", "lic": "Public domain", "by": "Orest Kiprensky", "src": "media/img/a9aa6bfcb8-360.webp", "w": 1000, "h": 1164, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Kiprensky_Pushkin.jpg/1280px-Kiprensky_Pushkin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Герой нашего времени", "a": "Михаил Лермонтов", "y": "1840", "ws": "Герой нашего времени (Лермонтов)", "q": "Я ехал на перекладных из Тифлиса.", "d": "Пять повестей о Печорине — «лишнем человеке», умном и разочарованном. Первый русский психологический роман.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Mikhail_lermontov.jpg", "lic": "Public domain", "by": "Petr Zabolotskiy", "src": "media/img/90a19f9994-360.webp", "w": 1000, "h": 1288, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Mikhail_lermontov.jpg/1280px-Mikhail_lermontov.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Мцыри", "a": "Михаил Лермонтов", "y": "1839", "ws": "Мцыри (Лермонтов)", "q": "", "d": "Романтическая поэма: юноша-послушник бежит из монастыря на три дня свободы. Исповедь бунтаря.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Mikhail_lermontov.jpg", "lic": "Public domain", "by": "Petr Zabolotskiy", "src": "media/img/90a19f9994-360.webp", "w": 1000, "h": 1288, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Mikhail_lermontov.jpg/1280px-Mikhail_lermontov.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Собор Парижской Богоматери", "a": "Виктор Гюго", "y": "1831", "ws": "Собор Парижской Богоматери (Гюго)", "q": "", "d": "Эсмеральда, звонарь Квазимодо и мрачный Фролло. Роман спас собор: после него Париж начал реставрацию готического шедевра.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Victor_Hugo_by_%C3%89tienne_Carjat_1876_-_full.jpg", "lic": "Public domain", "by": "Étienne Carjat", "src": "media/img/6b06b66375-360.webp", "w": 1000, "h": 1230, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/Victor_Hugo_by_%C3%89tienne_Carjat_1876_-_full.jpg/1280px-Victor_Hugo_by_%C3%89tienne_Carjat_1876_-_full.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Ворон", "a": "Эдгар По (перевод В. Брюсова)", "y": "1845", "ws": "Ворон (По; Брюсов)", "q": "", "d": "Ночью к тоскующему по умершей Ленор приходит ворон и твердит одно слово: «Nevermore» — «никогда».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Edgar_Allan_Poe_daguerreotype_crop.png", "lic": "Public domain", "by": "Unknown authorUnknown author; most likely George C. Gilchrest, Samuel P. Howes, ", "src": "media/img/04d08822cc-360.webp", "w": 1000, "h": 1400, "remote": "https://upload.wikimedia.org/wikipedia/commons/8/84/Edgar_Allan_Poe_daguerreotype_crop.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}], "quiz": [{"q": "Кто назвал «Евгения Онегина» «энциклопедией русской жизни»?", "o": ["Гоголь", "Белинский", "Толстой", "Тургенев"], "a": 1, "e": "Критик Виссарион Белинский."}, {"q": "Какой роман считают первым русским психологическим романом?", "o": ["«Евгений Онегин»", "«Герой нашего времени»", "«Мёртвые души»", "«Обломов»"], "a": 1, "e": "Лермонтов, 1840 год, герой — Григорий Печорин."}, {"q": "Типичный романтический герой — это…", "o": ["Добропорядочный чиновник", "Одинокий бунтарь в конфликте с обществом", "Весёлый крестьянин", "Мудрый правитель"], "a": 1, "e": "Байронический герой: изгнанник, гордец, мечтатель."}, {"q": "Что твердит ворон в стихотворении Эдгара По?", "o": ["«Forever»", "«Nevermore»", "«Remember»", "«Goodbye»"], "a": 1, "e": "«Nevermore» — «никогда больше»."}]}, {"id": "l6", "title": "Реализм в Европе", "period": "XIX век", "intro": ["Реализм — главный стиль XIX века. Писатели изображают общество как оно есть: деньги, карьера, бедность, быт, характер, сформированный средой. Роман становится главным жанром.", "Франция: Бальзак задумал «Человеческую комедию» — около сотни романов о всём французском обществе. Флобер в «Госпоже Бовари» довёл стиль до совершенства. Стендаль, Мопассан, Золя.", "Англия: Джейн Остин с ироничными романами о браке и нравах, Диккенс с его сиротами, злодеями и сатирой, сёстры Бронте, Теккерей."], "traits": ["Типичные характеры в типичных обстоятельствах", "Социальная тема: деньги, классы, среда", "Роман — главный жанр", "Франция: Бальзак, Стендаль, Флобер", "Англия: Остин, Диккенс, Бронте"], "works": [{"t": "Шагреневая кожа", "a": "Оноре де Бальзак", "y": "1831", "ws": "Шагреневая кожа (Бальзак; Аверкиев)", "q": "", "d": "Талисман исполняет любое желание, но каждое желание сокращает кожу — и жизнь владельца. Философская притча о цене страстей.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Honor%C3%A9_de_Balzac_(1842)_Detail.jpg", "lic": "Public domain", "by": "Louis-Auguste Bisson", "src": "media/img/7047817b44-360.webp", "w": 1000, "h": 909, "remote": "https://upload.wikimedia.org/wikipedia/commons/e/e6/Honor%C3%A9_de_Balzac_%281842%29_Detail.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Госпожа Бовари", "a": "Гюстав Флобер", "y": "1856", "ws": "Госпожа Бовари (Флобер; Ромм)", "q": "", "d": "Провинциальная жена врача мечтает о романтической жизни из книг. Флобер якобы сказал: «Эмма — это я».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Gustave_Flaubert.jpg", "lic": "Public domain", "by": "Nadar", "src": "media/img/907809b4ae-360.webp", "w": 1000, "h": 1102, "remote": "https://upload.wikimedia.org/wikipedia/commons/4/4f/Gustave_Flaubert.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Оливер Твист", "a": "Чарльз Диккенс", "y": "1838", "ws": "Оливер Твист (Диккенс)", "q": "", "d": "Сирота из работного дома попадает в банду лондонских воров. Диккенс заставил Англию увидеть детскую нищету.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Charles_Dickens_3.jpg", "lic": "Public domain", "by": "", "src": "media/img/310a6413ba-360.webp", "w": 1000, "h": 970, "remote": "https://upload.wikimedia.org/wikipedia/commons/4/48/Charles_Dickens_3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}], "quiz": [{"q": "Как называется цикл романов Бальзака?", "o": ["«Ругон-Маккары»", "«Человеческая комедия»", "«В поисках утраченного времени»", "«Сага о Форсайтах»"], "a": 1, "e": "«Человеческая комедия» — отсылка к «Божественной комедии» Данте."}, {"q": "Какой жанр — главный для реализма?", "o": ["Ода", "Роман", "Сонет", "Трагедия"], "a": 1, "e": "Роман позволяет показать общество широко и подробно."}, {"q": "Кто автор «Оливера Твиста»?", "o": ["Теккерей", "Диккенс", "Остин", "Скотт"], "a": 1, "e": "Чарльз Диккенс."}]}, {"id": "l7", "title": "Золотой век русской прозы", "period": "1840 — 1880-е", "intro": ["Во второй половине XIX века русская литература стала мировой. Гоголь открыл «маленького человека» и сатиру на чиновничью Россию. Тургенев создал портреты поколений и «тургеневских девушек». Гончаров — Обломова, Островский — русский театр.", "Два гиганта — Достоевский и Толстой. Достоевский — бездны человеческой души, преступление и вера, споры о Боге («Преступление и наказание», «Идиот», «Братья Карамазовы»). Толстой — огромная панорама жизни, «диалектика души», поиск смысла («Война и мир», «Анна Каренина»).", "Главные темы: «маленький человек», «лишний человек», вопрос «кто виноват?» и «что делать?», судьба народа, нравственный выбор."], "traits": ["«Маленький человек» (Гоголь)", "«Лишний человек» (Онегин, Печорин, Обломов)", "Психологизм: «диалектика души»", "Нравственные и религиозные вопросы", "Гоголь, Тургенев, Достоевский, Толстой"], "works": [{"t": "Шинель", "a": "Николай Гоголь", "y": "1842", "ws": "Шинель (Гоголь)", "q": "", "d": "Бедный чиновник Акакий Акакиевич копит на новую шинель — и её крадут. Классическая повесть о «маленьком человеке».", "img": {"page": "https://commons.wikimedia.org/wiki/File:N.Gogol_by_F.Moller_(1840,_Tretyakov_gallery).jpg", "lic": "Public domain", "by": "Otto Friedrich Theodor von Möller", "src": "media/img/c7c19e60d6-360.webp", "w": 1000, "h": 1261, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b2/N.Gogol_by_F.Moller_%281840%2C_Tretyakov_gallery%29.jpg/1280px-N.Gogol_by_F.Moller_%281840%2C_Tretyakov_gallery%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Мёртвые души", "a": "Николай Гоголь", "y": "1842", "ws": "Мёртвые души (Гоголь)", "q": "И какой же русский не любит быстрой езды?", "d": "Чичиков скупает умерших крестьян, числящихся живыми. Галерея помещиков — Манилов, Коробочка, Ноздрёв, Собакевич, Плюшкин.", "img": {"page": "https://commons.wikimedia.org/wiki/File:N.Gogol_by_F.Moller_(1840,_Tretyakov_gallery).jpg", "lic": "Public domain", "by": "Otto Friedrich Theodor von Möller", "src": "media/img/c7c19e60d6-360.webp", "w": 1000, "h": 1261, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b2/N.Gogol_by_F.Moller_%281840%2C_Tretyakov_gallery%29.jpg/1280px-N.Gogol_by_F.Moller_%281840%2C_Tretyakov_gallery%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Отцы и дети", "a": "Иван Тургенев", "y": "1862", "ws": "Отцы и дети (Тургенев)", "q": "Природа не храм, а мастерская, и человек в ней работник.", "d": "Нигилист Базаров против «отцов»-либералов. Конфликт поколений, который вечно актуален.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Turgenev_by_Repin.jpg", "lic": "Public domain", "by": "Ilya Repin", "src": "media/img/c3e7d708bf-360.webp", "w": 1000, "h": 1304, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/72/Turgenev_by_Repin.jpg/1280px-Turgenev_by_Repin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Преступление и наказание", "a": "Фёдор Достоевский", "y": "1866", "ws": "Преступление и наказание (Достоевский)", "q": "Тварь ли я дрожащая или право имею…", "d": "Студент Раскольников убивает старуху-процентщицу, чтобы проверить свою теорию. Роман о совести и искуплении.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Vasily_Perov_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%A4.%D0%9C.%D0%94%D0%BE%D1%81%D1%82%D0%BE%D0%B5%D0%B2%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Vasily Perov", "src": "media/img/223d7771e2-360.webp", "w": 1000, "h": 1250, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/Vasily_Perov_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%A4.%D0%9C.%D0%94%D0%BE%D1%81%D1%82%D0%BE%D0%B5%D0%B2%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_-_Google_Art_Project.jpg/1280px-Vasily_Perov_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%A4.%D0%9C.%D0%94%D0%BE%D1%81%D1%82%D0%BE%D0%B5%D0%B2%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Война и мир", "a": "Лев Толстой", "y": "1865–1869", "ws": "Война и мир", "q": "— Eh bien, mon prince. Gênes et Lucques ne sont plus que des apanages…", "d": "Роман-эпопея о войне 1812 года: Наташа Ростова, Пьер Безухов, Андрей Болконский. Около 600 персонажей.", "img": {"page": "https://commons.wikimedia.org/wiki/File:L.N.Tolstoy_Prokudin-Gorsky.jpg", "lic": "Public domain", "by": "Sergei Prokudin-Gorskii", "src": "media/img/a7a4c71e8c-360.webp", "w": 1000, "h": 1384, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/L.N.Tolstoy_Prokudin-Gorsky.jpg/1280px-L.N.Tolstoy_Prokudin-Gorsky.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Анна Каренина", "a": "Лев Толстой", "y": "1878", "ws": "Анна Каренина (Толстой)", "q": "Все счастливые семьи похожи друг на друга, каждая несчастливая семья несчастлива по-своему.", "d": "Две линии: трагическая любовь Анны и Вронского и поиски смысла Константином Лёвиным.", "img": {"page": "https://commons.wikimedia.org/wiki/File:L.N.Tolstoy_Prokudin-Gorsky.jpg", "lic": "Public domain", "by": "Sergei Prokudin-Gorskii", "src": "media/img/a7a4c71e8c-360.webp", "w": 1000, "h": 1384, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/L.N.Tolstoy_Prokudin-Gorsky.jpg/1280px-L.N.Tolstoy_Prokudin-Gorsky.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}], "quiz": [{"q": "Кто главный герой «Шинели»?", "o": ["Чичиков", "Акакий Акакиевич", "Раскольников", "Базаров"], "a": 1, "e": "Акакий Акакиевич Башмачкин."}, {"q": "Кем называет себя Базаров?", "o": ["Романтиком", "Нигилистом", "Славянофилом", "Декабристом"], "a": 1, "e": "Нигилист — человек, который ничего не принимает на веру."}, {"q": "Какая война в центре «Войны и мира»?", "o": ["Крымская", "Отечественная 1812 года", "Русско-турецкая", "Первая мировая"], "a": 1, "e": "Наполеоновские войны и 1812 год."}, {"q": "Что скупает Чичиков?", "o": ["Землю", "Мёртвые души — умерших крестьян", "Лошадей", "Картины"], "a": 1, "e": "Чтобы заложить их как живых в Опекунский совет."}]}, {"id": "l8", "title": "Чехов и Серебряный век", "period": "1880 — 1920-е", "intro": ["Антон Чехов изменил и прозу, и театр. Короткий рассказ, где «краткость — сестра таланта», и пьесы, где главное не в событиях, а в подтексте и настроении («Чайка», «Три сестры», «Вишнёвый сад»).", "Рубеж веков — Серебряный век русской поэзии. Символисты (Блок, Брюсов, Бальмонт) видят за миром тайну. Акмеисты (Гумилёв, Ахматова, Мандельштам) возвращают ясность и вещность. Футуристы (Маяковский, Хлебников) ломают язык. Отдельно стоят Цветаева, Есенин, Пастернак.", "Часть поэтов этой эпохи (Ахматова, Пастернак, Мандельштам) ещё охраняется авторским правом или их тексты ещё не попали в свободную библиотеку, поэтому здесь — те, кого уже можно читать свободно."], "traits": ["Чехов: подтекст, «краткость — сестра таланта»", "Символизм: Блок, Брюсов, Бальмонт", "Акмеизм: Гумилёв, Ахматова, Мандельштам", "Футуризм: Маяковский, Хлебников", "Цветаева, Есенин, Пастернак"], "works": [{"t": "Палата № 6", "a": "Антон Чехов", "y": "1892", "ws": "Палата № 6 (Чехов)", "q": "", "d": "Врач провинциальной больницы спорит с пациентом о страдании и сам оказывается в палате для душевнобольных. Ленин, прочитав, сказал, что почувствовал себя запертым в палате.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Anton_Chekhov_with_bow-tie_sepia_image.jpg", "lic": "Public domain", "by": "Unknown authorUnknown author", "src": "media/img/45a6b0ec50-360.webp", "w": 1000, "h": 1416, "remote": "https://upload.wikimedia.org/wikipedia/commons/c/c0/Anton_Chekhov_with_bow-tie_sepia_image.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Вишнёвый сад", "a": "Антон Чехов", "y": "1903", "ws": "Вишнёвый сад (Чехов)", "q": "Вся Россия наш сад.", "d": "Имение продают за долги, сад вырубают. Чехов называл пьесу комедией, а МХТ поставил её как драму.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Anton_Chekhov_with_bow-tie_sepia_image.jpg", "lic": "Public domain", "by": "Unknown authorUnknown author", "src": "media/img/45a6b0ec50-360.webp", "w": 1000, "h": 1416, "remote": "https://upload.wikimedia.org/wikipedia/commons/c/c0/Anton_Chekhov_with_bow-tie_sepia_image.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Незнакомка", "a": "Александр Блок", "y": "1906", "ws": "Незнакомка (Блок)", "q": "По вечерам над ресторанами\nГорячий воздух дик и глух…", "d": "Символизм: в пошлом загородном кабаке поэту является прекрасная Незнакомка — мечта или видение?", "img": {"page": "https://commons.wikimedia.org/wiki/File:Alexander_Blok_by_Ivan_Parkhomenko_1910.jpg", "lic": "Public domain", "by": "ru:Пархоменко, Иван Кириллович (1870-1940)", "src": "media/img/cee87e8a47-360.webp", "w": 1000, "h": 1113, "remote": "https://upload.wikimedia.org/wikipedia/commons/7/71/Alexander_Blok_by_Ivan_Parkhomenko_1910.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Двенадцать", "a": "Александр Блок", "y": "1918", "ws": "Двенадцать (Блок)", "q": "Черный вечер.\nБелый снег.\nВетер, ветер!", "d": "Поэма о революционном Петрограде: двенадцать красногвардейцев идут сквозь метель, а впереди — неожиданно — Христос.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Alexander_Blok_by_Ivan_Parkhomenko_1910.jpg", "lic": "Public domain", "by": "ru:Пархоменко, Иван Кириллович (1870-1940)", "src": "media/img/cee87e8a47-360.webp", "w": 1000, "h": 1113, "remote": "https://upload.wikimedia.org/wikipedia/commons/7/71/Alexander_Blok_by_Ivan_Parkhomenko_1910.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Мне нравится, что вы больны не мной…", "a": "Марина Цветаева", "y": "1915", "ws": "Мне нравится, что Вы больны не мной (Цветаева)", "q": "Мне нравится, что вы больны не мной,\nМне нравится, что я больна не вами…", "d": "Нежное и ироничное стихотворение, ставшее песней в фильме «Ирония судьбы»."}, {"t": "Письмо матери", "a": "Сергей Есенин", "y": "1924", "ws": "Письмо матери (Есенин)", "q": "Ты жива еще, моя старушка?\nЖив и я. Привет тебе, привет!", "d": "Исповедь блудного сына. Простые слова, песенная интонация — фирменный голос Есенина.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Sergey_Yesenin_2.jpg", "lic": "Public domain", "by": "Unknown authorUnknown author", "src": "media/img/8d42bf61f2-360.webp", "w": 1000, "h": 1332, "remote": "https://upload.wikimedia.org/wikipedia/commons/3/3a/Sergey_Yesenin_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}], "quiz": [{"q": "Кому принадлежат слова «Краткость — сестра таланта»?", "o": ["Толстому", "Чехову", "Гоголю", "Блоку"], "a": 1, "e": "Из письма Чехова брату Александру, 1889."}, {"q": "Блок — представитель какого направления?", "o": ["Акмеизма", "Символизма", "Футуризма", "Реализма"], "a": 1, "e": "Главный поэт русского символизма."}, {"q": "Кто из поэтов — футурист?", "o": ["Есенин", "Маяковский", "Гумилёв", "Цветаева"], "a": 1, "e": "Маяковский и Хлебников — лидеры русского футуризма."}, {"q": "Что происходит в «Вишнёвом саде»?", "o": ["Свадьба", "Имение с садом продают за долги", "Дуэль", "Революция"], "a": 1, "e": "Сад покупает Лопахин, сын бывшего крепостного."}]}]};
